/**
 * 🦊 Fox IA — version fichier unique
 *
 * Tout est ici : serveur, moteur IA, rendu 3D, générateur de sites et interface.
 * Démarrage :  npm install  puis  npm start
 *
 * Ne pas modifier à la main : ce fichier est généré par build-single.js
 */
'use strict';

/* ============ mini système de modules ============ */
const __mods = {};
function __def(name, fn) { __mods[name] = { fn, exports: null, loaded: false }; }
function __req(name) {
  const m = __mods[name];
  if (!m) return require(name);
  if (!m.loaded) {
    m.loaded = true;
    const module = { exports: {} };
    m.fn(module, module.exports, __req);
    m.exports = module.exports;
  }
  return m.exports;
}

/* ============ interface embarquée ============ */
const __ASSETS = {
  "/index.html": { mime: "text/html; charset=utf-8", b64: "" },
  "/style.css": { mime: "text/css; charset=utf-8", b64: "" },
  "/app.js": { mime: "application/javascript; charset=utf-8", b64: "" },
};


/* ============ modules ============ */
__def("db", function(module, exports, __req){
/**
 * Fox IA — couche base de données.
 *
 * Deux moteurs, une seule API :
 *   • PostgreSQL  si DATABASE_URL est défini  → production (Render + Neon)
 *   • SQLite      sinon                       → développement local
 *
 * Toutes les méthodes sont asynchrones : get / all / run.
 */
const PG = Boolean(process.env.DATABASE_URL);

let pool = null, sqlite = null;

if (PG) {
  const { Pool } = require('pg');
  pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    ssl: process.env.DATABASE_URL.includes('localhost') ? false : { rejectUnauthorized: false },
    max: 5
  });
} else {
  let Database;
  try { Database = require('better-sqlite3'); }
  catch (e) {
    console.error("\n❌ Aucune base disponible.\n" +
      "   • En local : lance `npm install` (installe SQLite).\n" +
      "   • En production : définis la variable DATABASE_URL (PostgreSQL).\n");
    process.exit(1);
  }
  const path = require('path'), fs = require('fs');
  const dir = path.join(__dirname, '..', 'data');
  fs.mkdirSync(dir, { recursive: true });
  sqlite = new Database(path.join(dir, 'foxia.db'));
  sqlite.pragma('journal_mode = WAL');
}

/* ---- tables sans colonne id ---- */
const NO_ID = new Set(['settings', 'files']);

/* ---- traduction SQLite → PostgreSQL ---- */
function toPg(sql) {
  let i = 0;
  return sql
    .replace(/\?/g, () => `$${++i}`)
    .replace(/datetime\('now'\)/gi, 'NOW()')
    .replace(/date\('now'\)/gi, 'CURRENT_DATE')
    .replace(/date\(created_at\)/gi, 'created_at::date')
    .replace(/COLLATE NOCASE/gi, '')
    .replace(/INTEGER PRIMARY KEY AUTOINCREMENT/gi, 'SERIAL PRIMARY KEY');
}

const q = {
  async all(sql, params = []) {
    if (PG) return (await pool.query(toPg(sql), params)).rows;
    return sqlite.prepare(sql).all(...params);
  },
  async get(sql, params = []) {
    if (PG) return (await pool.query(toPg(sql), params)).rows[0] || undefined;
    return sqlite.prepare(sql).get(...params);
  },
  async run(sql, params = []) {
    if (PG) {
      // "RETURNING id" uniquement pour les INSERT sur une table qui possède un id
      const m = sql.match(/^\s*INSERT\s+INTO\s+([a-z_]+)/i);
      const ins = m && !NO_ID.has(m[1].toLowerCase()) && !/RETURNING/i.test(sql);
      const r = await pool.query(toPg(sql) + (ins ? ' RETURNING id' : ''), params);
      return { lastInsertRowid: r.rows?.[0]?.id, changes: r.rowCount };
    }
    const r = sqlite.prepare(sql).run(...params);
    return { lastInsertRowid: r.lastInsertRowid, changes: r.changes };
  },
  async exec(sql) {
    if (PG) return pool.query(sql);
    return sqlite.exec(sql);
  }
};

/* ---- comparaison insensible à la casse (portable) ---- */
const CI = (col) => PG ? `LOWER(${col})` : col;

/* ---- schéma ---- */
async function init() {
  const ID = PG ? 'SERIAL PRIMARY KEY' : 'INTEGER PRIMARY KEY AUTOINCREMENT';
  const NOW = PG ? 'NOW()' : "(datetime('now'))";

  await q.exec(`CREATE TABLE IF NOT EXISTS users (
    id ${ID},
    pseudo TEXT UNIQUE NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT,
    provider TEXT NOT NULL DEFAULT 'email',
    avatar TEXT,
    role TEXT NOT NULL DEFAULT 'user',
    banned INTEGER NOT NULL DEFAULT 0,
    credits INTEGER NOT NULL DEFAULT 100,
    reset_token TEXT,
    reset_expires TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  await q.exec(`CREATE TABLE IF NOT EXISTS tickets (
    id ${ID},
    user_id INTEGER,
    pseudo TEXT, email TEXT,
    category TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL,
    priority TEXT NOT NULL DEFAULT 'normale',
    status TEXT NOT NULL DEFAULT 'ouvert',
    admin_reply TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW},
    updated_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  await q.exec(`CREATE TABLE IF NOT EXISTS creations (
    id ${ID}, user_id INTEGER NOT NULL, type TEXT NOT NULL,
    prompt TEXT NOT NULL, file TEXT, meta TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  await q.exec(`CREATE TABLE IF NOT EXISTS messages (
    id ${ID}, user_id INTEGER NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  await q.exec(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)`);

  // Fichiers générés stockés en base : le disque de Render est effacé
  // à chaque redéploiement, la base ne l'est pas.
  await q.exec(`CREATE TABLE IF NOT EXISTS files (
    name TEXT PRIMARY KEY, mime TEXT NOT NULL, content TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  await q.exec(`CREATE TABLE IF NOT EXISTS logs (
    id ${ID}, level TEXT NOT NULL DEFAULT 'info', event TEXT NOT NULL, detail TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT ${NOW}
  )`);

  // migration douce : colonnes de réinitialisation sur bases existantes
  for (const c of ['reset_token TEXT', 'reset_expires TEXT']) {
    try { await q.exec(`ALTER TABLE users ADD COLUMN ${c}`); } catch (e) {}
  }

  const defaults = { site_name: 'Fox IA', announcement: '', maintenance: '0', signups_open: '1' };
  for (const [k, v] of Object.entries(defaults)) {
    if ((await getSetting(k)) === null) await setSetting(k, v);
  }
}

async function setSetting(k, v) {
  await q.run('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', [k, String(v)]);
}
async function getSetting(k, d = null) {
  const r = await q.get('SELECT value FROM settings WHERE key=?', [k]);
  return r ? r.value : d;
}
async function log(event, detail = '', level = 'info') {
  try { await q.run('INSERT INTO logs(level,event,detail) VALUES(?,?,?)', [level, event, String(detail).slice(0, 800)]); } catch (e) {}
}

module.exports = { q, init, setSetting, getSetting, log, PG, CI };

});

__def("ai", function(module, exports, __req){
/**
 * Fox IA — moteur d'intelligence.
 *
 * Deux modes :
 *  1) MODE CONNECTÉ : si une clé API est présente dans .env (OPENAI_API_KEY ou
 *     compatible), Fox IA appelle le vrai modèle pour le chat et les images.
 *  2) MODE LOCAL (par défaut, aucune clé requise) : Fox IA utilise son moteur
 *     génératif interne — rendu procédural 3D en SVG haute définition,
 *     compositeur vidéo par scènes animées, et générateur de sites web.
 */
const fetch = require('node-fetch');

const API_KEY = process.env.OPENAI_API_KEY || '';
const API_BASE = process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1';
const CHAT_MODEL = process.env.FOXIA_CHAT_MODEL || 'gpt-4o-mini';
const IMAGE_MODEL = process.env.FOXIA_IMAGE_MODEL || 'gpt-image-1';
const connected = () => Boolean(API_KEY);

const SYSTEM = `Tu es Fox IA, une intelligence artificielle française, chaleureuse, précise et créative.
Tu sais discuter, générer des images 3D 4K, produire des vidéos animées et créer des sites web complets.
Réponds toujours en français, de façon structurée et concrète.`;

/* ------------------------------------------------------------------ */
/* CHAT                                                                */
/* ------------------------------------------------------------------ */
async function chat(history, message) {
  if (connected()) {
    try {
      const msgs = [{ role: 'system', content: SYSTEM }];
      history.slice(-12).forEach(m => msgs.push({ role: m.role, content: m.content }));
      msgs.push({ role: 'user', content: message });
      const r = await fetch(`${API_BASE}/chat/completions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${API_KEY}` },
        body: JSON.stringify({ model: CHAT_MODEL, messages: msgs, temperature: 0.8 })
      });
      const j = await r.json();
      const txt = j?.choices?.[0]?.message?.content;
      if (txt) return { text: txt, engine: 'connected' };
    } catch (e) { /* bascule en local */ }
  }
  return { text: localChat(message), engine: 'local' };
}

const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

function localChat(message) {
  const m = norm(message);
  const has = (...w) => w.some(x => m.includes(x));

  if (has('bonjour', 'salut', 'coucou', 'hello', 'bonsoir', 'yo '))
    return `Salut ! Je suis **Fox IA** 🦊\n\nVoici ce que je sais faire :\n\n• **Images 3D 4K** — décris une scène, je la rends en très haute définition\n• **Vidéos** — j'anime tes idées en séquences fluides\n• **Sites web** — un prompt, un site complet livré en HTML\n• **Discussion** — je réponds, j'organise, je propose\n\nPar quoi on commence ?`;

  if (has('qui es tu', 'qui es-tu', 'ton nom', 'tu es qui', 'presente'))
    return `Je suis **Fox IA**, ton assistant créatif personnel 🦊\n\nJe vis dans ce studio et je gère quatre ateliers : le **Chat**, le **Studio Image 3D**, le **Studio Vidéo** et le **Web Builder**. Chaque création que tu fais est enregistrée dans ta **Galerie**.\n\nDis-moi ce que tu veux créer.`;

  if (has('image', 'photo', 'dessin', 'illustration', 'rendu 3d', 'visuel'))
    return `Pour une image, file dans l'onglet **Image 3D** 🎨\n\nQuelques conseils pour un rendu qui claque :\n\n1. **Le sujet** — "un renard mécanique", "une cité flottante"\n2. **L'ambiance** — néon, coucher de soleil, brouillard, cyberpunk\n3. **Les couleurs** — violet et cyan, or et noir...\n4. **Le cadrage** — gros plan, vue aérienne, plan large\n\nExemple : *un renard de cristal dans une forêt néon violette, brume, vue rapprochée*`;

  if (has('video', 'vidéo', 'film', 'anim', 'clip'))
    return `Direction l'onglet **Vidéo** 🎬\n\nDécris ta scène et choisis la durée. Je découpe automatiquement en séquences animées avec caméra mobile, puis tu peux **exporter en .webm**.\n\nExemple : *survol d'une ville futuriste au crépuscule, lumières violettes, caméra qui avance*`;

  if (has('site', 'web', 'page', 'landing', 'html'))
    return `L'onglet **Web Builder** est fait pour ça 🌐\n\nDonne-moi : le **type de site** (portfolio, restaurant, boutique, SaaS...), le **nom**, et l'**ambiance** voulue. Je génère un site complet, responsive, prêt à télécharger.\n\nExemple : *un site pour un salon de coiffure haut de gamme à Pau, ambiance dorée et sobre*`;

  if (has('bug', 'probleme', 'marche pas', 'erreur', 'signaler'))
    return `Désolé pour la gêne 😕\n\nUtilise le bouton **Support** tout en bas du site : ton ticket part directement vers l'interface administrateur, avec un numéro de suivi. L'admin le voit en temps réel et peut te répondre.`;

  if (has('merci', 'super', 'genial', 'nickel', 'parfait'))
    return `Avec plaisir ! 🦊 Je suis là quand tu veux. On enchaîne sur une image, une vidéo ou un site ?`;

  if (has('aide', 'help', 'comment', 'tuto'))
    return `**Guide express de Fox IA** 🦊\n\n| Onglet | Ce que ça fait |\n|---|---|\n| 💬 Chat | On discute, je te conseille |\n| 🎨 Image 3D | Rendu procédural jusqu'en 4K, export PNG |\n| 🎬 Vidéo | Scènes animées, export .webm |\n| 🌐 Web | Site complet à partir d'un prompt |\n| 🖼️ Galerie | Toutes tes créations sauvegardées |\n\nEt en bas de page : le **Support** pour joindre l'administrateur.`;

  const seeds = [
    `Bien reçu 🦊 — "**${message.trim().slice(0, 120)}**".\n\nJe peux transformer ça en **image 3D**, en **vidéo animée** ou en **site web**. Dis-moi le format et je m'y mets.`,
    `Intéressant ! Sur "**${message.trim().slice(0, 120)}**", voici ce que je propose :\n\n1. Un rendu **visuel 3D** pour poser l'ambiance\n2. Une **animation** courte pour la mettre en mouvement\n3. Une **page web** pour la présenter\n\nOn part sur lequel ?`,
    `Noté 🦊\n\nPour avancer sur "**${message.trim().slice(0, 120)}**", précise-moi le **rendu attendu** (image, vidéo, site) et l'**ambiance** — je m'occupe du reste.`
  ];
  return seeds[Math.abs(hash(message)) % seeds.length];
}

/* ------------------------------------------------------------------ */
/* ANALYSE DE PROMPT — le cœur du moteur local                         */
/* ------------------------------------------------------------------ */
function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h | 0;
}
function rng(seed) {
  let s = seed >>> 0 || 1;
  return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
}

const PALETTES = {
  neon:      { name: 'Néon', bg: ['#0a0118', '#1b0736'], hues: ['#8b5cf6', '#22d3ee', '#f472b6', '#a78bfa'], glow: '#22d3ee', sky: '#150b2e' },
  sunset:    { name: 'Coucher de soleil', bg: ['#2a0a2e', '#7c2d12'], hues: ['#fb923c', '#f43f5e', '#fbbf24', '#e879f9'], glow: '#fb923c', sky: '#4a1533' },
  ocean:     { name: 'Océan', bg: ['#021024', '#083344'], hues: ['#22d3ee', '#38bdf8', '#5eead4', '#818cf8'], glow: '#38bdf8', sky: '#052034' },
  forest:    { name: 'Forêt', bg: ['#04150e', '#0f3d2e'], hues: ['#34d399', '#a3e635', '#10b981', '#fde047'], glow: '#34d399', sky: '#07241a' },
  gold:      { name: 'Or', bg: ['#140f02', '#3f2d09'], hues: ['#fbbf24', '#f59e0b', '#fde68a', '#d97706'], glow: '#fbbf24', sky: '#241a05' },
  ice:       { name: 'Glace', bg: ['#071426', '#1e3a5f'], hues: ['#bae6fd', '#7dd3fc', '#e0f2fe', '#a5b4fc'], glow: '#bae6fd', sky: '#0d2338' },
  blood:     { name: 'Braise', bg: ['#1a0505', '#4c0519'], hues: ['#ef4444', '#f97316', '#fda4af', '#dc2626'], glow: '#ef4444', sky: '#2b0a0f' },
  mono:      { name: 'Monochrome', bg: ['#0a0a0a', '#262626'], hues: ['#e5e5e5', '#a3a3a3', '#fafafa', '#737373'], glow: '#ffffff', sky: '#171717' }
};

const SUBJECTS = {
  fox:      ['renard', 'fox', 'goupil'],
  city:     ['ville', 'cite', 'city', 'building', 'immeuble', 'urbain', 'gratte-ciel', 'metropole'],
  mountain: ['montagne', 'pic', 'sommet', 'alpes', 'pyrenee', 'colline', 'vallee'],
  space:    ['espace', 'galaxie', 'planete', 'etoile', 'cosmos', 'nebuleuse', 'astro', 'lune', 'univers'],
  ocean:    ['mer', 'ocean', 'vague', 'plage', 'eau', 'sous-marin', 'lac'],
  forest:   ['foret', 'arbre', 'bois', 'jungle', 'nature', 'feuille'],
  abstract: ['abstrait', 'forme', 'geometri', 'cristal', 'sphere', 'cube', 'fractal', 'polygone'],
  portrait: ['portrait', 'visage', 'personnage', 'humain', 'femme', 'homme', 'robot', 'androide'],
  car:      ['voiture', 'auto', 'bolide', 'moto', 'vehicule', 'course'],
  castle:   ['chateau', 'temple', 'ruine', 'tour', 'palais', 'cathedrale']
};

function analyze(prompt) {
  const m = norm(prompt);
  const seed = hash(prompt);
  const r = rng(seed);

  // palette
  let pal = 'neon';
  const palHints = {
    sunset: ['coucher', 'sunset', 'crepuscule', 'orange', 'aube', 'soleil', 'chaud'],
    ocean:  ['mer', 'ocean', 'bleu', 'eau', 'aqua', 'marin', 'vague'],
    forest: ['foret', 'vert', 'nature', 'jungle', 'arbre', 'emeraude'],
    gold:   ['or', 'dore', 'gold', 'luxe', 'prestige', 'ambre', 'jaune'],
    ice:    ['glace', 'neige', 'hiver', 'froid', 'givre', 'blanc', 'arctique'],
    blood:  ['rouge', 'feu', 'braise', 'lave', 'sang', 'volcan', 'infernal'],
    mono:   ['noir et blanc', 'monochrome', 'gris', 'sobre', 'minimal'],
    neon:   ['neon', 'cyberpunk', 'violet', 'futur', 'nuit', 'synthwave', 'cyber']
  };
  let best = 0;
  for (const [k, words] of Object.entries(palHints)) {
    const score = words.reduce((a, w) => a + (m.includes(w) ? 1 : 0), 0);
    if (score > best) { best = score; pal = k; }
  }

  // sujet — correspondance par mot entier (évite que "château" matche "eau")
  const words_in = m.split(/[^a-z0-9]+/).filter(Boolean);
  const matches = (w) => words_in.some(t => t === w || (w.length >= 5 && t.startsWith(w)) || (t.length >= 5 && w.startsWith(t)));
  let subject = 'abstract', sbest = 0;
  for (const [k, words] of Object.entries(SUBJECTS)) {
    const score = words.reduce((a, w) => a + (matches(w) ? 1 : 0), 0);
    if (score > sbest) { sbest = score; subject = k; }
  }
  if (sbest === 0) subject = ['abstract', 'city', 'mountain', 'space'][Math.abs(seed) % 4];

  return {
    seed, r,
    palette: PALETTES[pal],
    paletteKey: pal,
    subject,
    night: /nuit|night|sombre|dark|obscur|minuit/.test(m) || pal === 'neon',
    fog:   /brume|brouillard|fog|mist|vapeur|nuage/.test(m),
    rain:  /pluie|rain|orage|tempete/.test(m),
    snow:  /neige|snow|flocon/.test(m),
    stars: /etoile|star|espace|galaxie|cosmos|nuit/.test(m),
    closeup: /gros plan|closeup|close-up|macro|pres/.test(m),
    aerial: /aerien|drone|vue de haut|survol|dessus/.test(m),
    glow: /neon|lumineux|brillant|glow|eclat|lumiere/.test(m) || pal === 'neon'
  };
}

module.exports = { chat, analyze, hash, rng, PALETTES, connected, localChat };

});

__def("render", function(module, exports, __req){
/**
 * Fox IA — moteur de rendu 3D procédural.
 * Produit du SVG vectoriel (donc net à n'importe quelle résolution, 4K inclus)
 * avec perspective, profondeur de champ, éclairage volumétrique et ombres.
 */
const { analyze, rng } = __req('ai');

const R = (n, d = 2) => Number(n.toFixed(d));

function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) + amt, g = ((n >> 8) & 255) + amt, b = (n & 255) + amt;
  r = Math.max(0, Math.min(255, r)); g = Math.max(0, Math.min(255, g)); b = Math.max(0, Math.min(255, b));
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

/* ---------- éléments de scène ---------- */

function skyLayer(a, W, H) {
  const p = a.palette;
  let s = `<rect width="${W}" height="${H}" fill="url(#sky)"/>`;
  if (a.stars) {
    const r = rng(a.seed ^ 0x51ed);
    for (let i = 0; i < 220; i++) {
      const x = R(r() * W), y = R(r() * H * 0.68), rad = R(r() * 2.2 + 0.4), o = R(r() * 0.85 + 0.15);
      s += `<circle cx="${x}" cy="${y}" r="${rad}" fill="#fff" opacity="${o}"/>`;
    }
    for (let i = 0; i < 5; i++) {
      const x = R(r() * W), y = R(r() * H * 0.5), rad = R(r() * 60 + 40);
      s += `<circle cx="${x}" cy="${y}" r="${rad}" fill="${p.hues[i % p.hues.length]}" opacity="0.10" filter="url(#soft)"/>`;
    }
  }
  // astre
  const r2 = rng(a.seed ^ 0x9a1);
  const sx = R(W * (0.15 + r2() * 0.7)), sy = R(H * (0.12 + r2() * 0.22)), sr = R(W * 0.045 + r2() * W * 0.03);
  s += `<circle cx="${sx}" cy="${sy}" r="${sr * 3.4}" fill="${p.glow}" opacity="0.13" filter="url(#soft)"/>`;
  s += `<circle cx="${sx}" cy="${sy}" r="${sr * 1.8}" fill="${p.glow}" opacity="0.20" filter="url(#soft)"/>`;
  s += `<circle cx="${sx}" cy="${sy}" r="${sr}" fill="${shade(p.glow, 60)}" opacity="0.95"/>`;
  return { svg: s, sun: { x: sx, y: sy, r: sr } };
}

function mountains(a, W, H, horizon) {
  const p = a.palette;
  let s = '';
  for (let layer = 3; layer >= 0; layer--) {
    const r = rng(a.seed ^ (layer * 7919));
    const depth = layer / 3;
    const base = horizon + depth * H * 0.06;
    const amp = H * (0.30 - depth * 0.16);
    let d = `M -20 ${R(base + 40)} L -20 ${R(base)}`;
    const steps = 14 + layer * 4;
    for (let i = 0; i <= steps; i++) {
      const x = R(-20 + (W + 40) * (i / steps));
      const n = Math.sin(i * 1.7 + layer * 2.3) * 0.5 + Math.sin(i * 0.6 + layer) * 0.3 + r() * 0.45;
      const y = R(base - Math.abs(n) * amp);
      d += ` L ${x} ${y}`;
    }
    d += ` L ${W + 20} ${R(base + 40)} Z`;
    const col = shade(p.bg[1], -30 + layer * 26);
    s += `<path d="${d}" fill="${col}" opacity="${R(0.55 + depth * 0.4)}"/>`;
    if (layer === 0 && a.glow)
      s += `<path d="${d}" fill="none" stroke="${p.hues[1]}" stroke-width="1.6" opacity="0.5" filter="url(#glow)"/>`;
  }
  return s;
}

function cityScape(a, W, H, horizon) {
  const p = a.palette;
  const r = rng(a.seed ^ 0xc17a);
  let s = '';
  // 3 plans de profondeur
  for (let layer = 2; layer >= 0; layer--) {
    const depth = layer / 2;
    const baseY = horizon + depth * H * 0.13 + H * 0.015;
    const maxH = H * (0.42 - depth * 0.20);
    const bw = W * (0.045 + depth * 0.03);
    let x = -bw;
    while (x < W + bw) {
      const w = R(bw * (0.55 + r() * 0.95));
      const h = R(maxH * (0.25 + r() * 0.95));
      const y = R(baseY - h);
      const face = shade(p.bg[1], -22 + layer * 24);
      const side = shade(p.bg[1], -40 + layer * 20);
      const dx = R(w * 0.20 * (1 - depth));
      // volume 3D : face + côté + toit
      s += `<polygon points="${R(x)},${R(baseY)} ${R(x)},${y} ${R(x + w)},${y} ${R(x + w)},${R(baseY)}" fill="${face}"/>`;
      s += `<polygon points="${R(x + w)},${y} ${R(x + w + dx)},${R(y - dx * 0.55)} ${R(x + w + dx)},${R(baseY - dx * 0.55)} ${R(x + w)},${R(baseY)}" fill="${side}"/>`;
      s += `<polygon points="${R(x)},${y} ${R(x + dx)},${R(y - dx * 0.55)} ${R(x + w + dx)},${R(y - dx * 0.55)} ${R(x + w)},${y}" fill="${shade(face, 14)}"/>`;
      // fenêtres
      if (layer <= 1) {
        const cols = Math.max(2, Math.floor(w / (W * 0.011)));
        const rows = Math.max(3, Math.floor(h / (H * 0.026)));
        for (let c = 0; c < cols; c++) for (let ro = 0; ro < rows; ro++) {
          if (r() > 0.42) continue;
          const wx = R(x + w * 0.12 + c * (w * 0.76 / cols));
          const wy = R(y + h * 0.06 + ro * (h * 0.88 / rows));
          const ww = R(w * 0.76 / cols * 0.55), wh = R(h * 0.88 / rows * 0.45);
          s += `<rect x="${wx}" y="${wy}" width="${ww}" height="${wh}" fill="${p.hues[Math.floor(r() * p.hues.length)]}" opacity="${R(0.45 + r() * 0.55)}"/>`;
        }
        // antenne
        if (r() > 0.72) {
          s += `<rect x="${R(x + w / 2 - w * 0.02)}" y="${R(y - h * 0.18)}" width="${R(w * 0.04)}" height="${R(h * 0.18)}" fill="${side}"/>`;
          s += `<circle cx="${R(x + w / 2)}" cy="${R(y - h * 0.19)}" r="${R(w * 0.045)}" fill="${p.hues[0]}" filter="url(#glow)"/>`;
        }
      }
      x += w + bw * (0.10 + r() * 0.25);
    }
  }
  return s;
}

function waterPlane(a, W, H, horizon) {
  const p = a.palette;
  const r = rng(a.seed ^ 0x0cea);
  let s = `<rect x="0" y="${R(horizon)}" width="${W}" height="${R(H - horizon)}" fill="url(#water)"/>`;
  for (let i = 0; i < 60; i++) {
    const t = i / 60;
    const y = R(horizon + Math.pow(t, 1.9) * (H - horizon));
    const w = R(W * (0.04 + t * 0.35) * (0.3 + r()));
    const x = R(r() * W);
    s += `<rect x="${x}" y="${y}" width="${w}" height="${R(1 + t * 3.5)}" rx="${R(1 + t * 2)}" fill="${p.hues[Math.floor(r() * p.hues.length)]}" opacity="${R(0.10 + t * 0.35)}"/>`;
  }
  return s;
}

function groundGrid(a, W, H, horizon) {
  const p = a.palette;
  let s = `<rect x="0" y="${R(horizon)}" width="${W}" height="${R(H - horizon)}" fill="url(#ground)"/>`;
  const cx = W / 2;
  // lignes de fuite
  for (let i = -18; i <= 18; i++) {
    const x2 = cx + i * (W / 9);
    s += `<line x1="${R(cx + i * 8)}" y1="${R(horizon)}" x2="${R(x2)}" y2="${H}" stroke="${p.hues[0]}" stroke-width="1.2" opacity="0.22"/>`;
  }
  // lignes horizontales en perspective
  for (let i = 1; i <= 26; i++) {
    const t = i / 26;
    const y = R(horizon + Math.pow(t, 2.2) * (H - horizon));
    s += `<line x1="0" y1="${y}" x2="${W}" y2="${y}" stroke="${p.hues[1]}" stroke-width="${R(0.6 + t * 1.8)}" opacity="${R(0.10 + t * 0.30)}"/>`;
  }
  return s;
}

function foxSilhouette(a, W, H, horizon) {
  const p = a.palette;
  const cx = W * 0.46, base = horizon + (H - horizon) * 0.80;
  const sc = (H * 0.40) / 100;
  const T = (x, y) => `${R(cx + x * sc)},${R(base - y * sc)}`;
  // corps low-poly (le sol est à y=0, les pattes descendent jusque-là)
  const body = [T(-44, 26), T(-30, 44), T(-4, 50), T(22, 46), T(40, 34), T(46, 24), T(34, 22), T(22, 28), T(-6, 31), T(-30, 24)].join(' ');
  const head = [T(34, 42), T(38, 60), T(48, 68), T(60, 62), T(66, 50), T(62, 38), T(48, 32), T(36, 34)].join(' ');
  const earL = [T(37, 58), T(36, 78), T(48, 64)].join(' ');
  const earR = [T(60, 60), T(68, 76), T(67, 54)].join(' ');
  const snout = [T(66, 50), T(84, 44), T(66, 40)].join(' ');
  const tail = [T(-44, 26), T(-70, 44), T(-84, 68), T(-66, 62), T(-50, 42), T(-38, 32)].join(' ');
  const legs = [[-22, 0, 0], [-6, 0, 0], [16, 0, 0], [32, 0, 0]]
    .map(([x]) => `<polygon points="${T(x - 5, 0)} ${T(x + 5, 0)} ${T(x + 4.5, 36)} ${T(x - 4.5, 36)}" fill="${shade(p.hues[0], -60)}"/>`).join('');

  let s = `<g filter="url(#dof0)">`;
  s += `<ellipse cx="${R(cx)}" cy="${R(base + 4)}" rx="${R(sc * 90)}" ry="${R(sc * 11)}" fill="#000" opacity="0.45" filter="url(#soft)"/>`;
  s += `<ellipse cx="${R(cx)}" cy="${R(base - sc * 42)}" rx="${R(sc * 100)}" ry="${R(sc * 62)}" fill="${p.glow}" opacity="0.12" filter="url(#soft)"/>`;
  s += legs;
  s += `<polygon points="${tail}" fill="${shade(p.hues[0], -18)}"/>`;
  s += `<polygon points="${body}" fill="${p.hues[0]}"/>`;
  s += `<polygon points="${body}" fill="url(#rim)" opacity="0.55"/>`;
  s += `<polygon points="${earL}" fill="${shade(p.hues[0], -34)}"/><polygon points="${earR}" fill="${shade(p.hues[0], -34)}"/>`;
  s += `<polygon points="${head}" fill="${shade(p.hues[0], 20)}"/>`;
  s += `<polygon points="${snout}" fill="${shade(p.hues[0], -10)}"/>`;
  s += `<polygon points="${head}" fill="url(#rim)" opacity="0.45"/>`;
  // œil lumineux
  s += `<circle cx="${R(cx + 54 * sc)}" cy="${R(base - 52 * sc)}" r="${R(sc * 5)}" fill="${p.hues[1]}" filter="url(#glow)"/>`;
  s += `<circle cx="${R(cx + 54 * sc)}" cy="${R(base - 52 * sc)}" r="${R(sc * 2)}" fill="#fff"/>`;
  // arêtes low-poly
  s += `<polyline points="${T(-30, 44)} ${T(-4, 50)} ${T(22, 46)} ${T(40, 34)}" fill="none" stroke="${shade(p.hues[0], 70)}" stroke-width="${R(sc * 1.1)}" opacity="0.5"/>`;
  s += `</g>`;
  return s;
}

function crystals(a, W, H, horizon) {
  const p = a.palette;
  const r = rng(a.seed ^ 0xc4a5);
  let s = '';
  const n = 9;
  const items = [];
  for (let i = 0; i < n; i++) items.push({ x: r(), z: r(), s: 0.3 + r() * 0.9, h: r(), c: Math.floor(r() * p.hues.length) });
  items.sort((a1, b1) => a1.z - b1.z);
  items.forEach((it, i) => {
    const depth = it.z;
    const cx = W * (0.06 + it.x * 0.88);
    const base = horizon + Math.pow(depth, 1.5) * (H - horizon) * 0.95;
    const sz = (H * 0.06 + it.s * H * 0.26) * (0.35 + depth * 0.95);
    const w = sz * (0.30 + it.h * 0.24);
    const col = p.hues[it.c];
    const pts = `${R(cx)},${R(base - sz)} ${R(cx + w)},${R(base - sz * 0.42)} ${R(cx + w * 0.62)},${R(base)} ${R(cx - w * 0.62)},${R(base)} ${R(cx - w)},${R(base - sz * 0.42)}`;
    const f = depth > 0.72 ? '' : ` filter="url(#dof${depth > 0.4 ? 1 : 2})"`;
    s += `<g${f}>`;
    s += `<ellipse cx="${R(cx)}" cy="${R(base + 3)}" rx="${R(w * 1.25)}" ry="${R(w * 0.24)}" fill="#000" opacity="0.4" filter="url(#soft)"/>`;
    s += `<ellipse cx="${R(cx)}" cy="${R(base - sz * 0.5)}" rx="${R(w * 2.4)}" ry="${R(sz * 0.9)}" fill="${col}" opacity="0.13" filter="url(#soft)"/>`;
    s += `<polygon points="${pts}" fill="${col}" opacity="0.88"/>`;
    s += `<polygon points="${R(cx)},${R(base - sz)} ${R(cx + w)},${R(base - sz * 0.42)} ${R(cx + w * 0.62)},${R(base)} ${R(cx)},${R(base - sz * 0.18)}" fill="${shade(col, -48)}" opacity="0.85"/>`;
    s += `<polygon points="${R(cx)},${R(base - sz)} ${R(cx - w * 0.35)},${R(base - sz * 0.5)} ${R(cx)},${R(base - sz * 0.18)}" fill="${shade(col, 80)}" opacity="0.55"/>`;
    s += `<polygon points="${pts}" fill="none" stroke="${shade(col, 90)}" stroke-width="1.3" opacity="0.6"/>`;
    s += `</g>`;
  });
  return s;
}

function planets(a, W, H) {
  const p = a.palette;
  const r = rng(a.seed ^ 0x9139);
  let s = '';
  for (let i = 0; i < 4; i++) {
    const cx = R(W * (0.08 + r() * 0.84)), cy = R(H * (0.10 + r() * 0.62));
    const rad = R(W * (0.02 + r() * 0.10));
    const col = p.hues[i % p.hues.length];
    s += `<circle cx="${cx}" cy="${cy}" r="${R(rad * 2.6)}" fill="${col}" opacity="0.10" filter="url(#soft)"/>`;
    s += `<circle cx="${cx}" cy="${cy}" r="${rad}" fill="${shade(col, -30)}"/>`;
    s += `<circle cx="${cx}" cy="${cy}" r="${rad}" fill="url(#sphere)"/>`;
    s += `<ellipse cx="${cx}" cy="${cy}" rx="${R(rad * 0.8)}" ry="${R(rad * 0.3)}" fill="${shade(col, 50)}" opacity="0.22"/>`;
    if (r() > 0.55)
      s += `<ellipse cx="${cx}" cy="${cy}" rx="${R(rad * 1.9)}" ry="${R(rad * 0.42)}" fill="none" stroke="${shade(col, 60)}" stroke-width="${R(rad * 0.13)}" opacity="0.65" transform="rotate(${R(-25 + r() * 50)} ${cx} ${cy})"/>`;
  }
  return s;
}

function trees(a, W, H, horizon, maxZ = 1) {
  const p = a.palette;
  const r = rng(a.seed ^ 0x7ee5);
  let s = '';
  const items = [];
  for (let i = 0; i < 40; i++) items.push({ x: r(), z: r() * maxZ, s: 0.5 + r() });
  items.sort((x, y) => x.z - y.z);
  items.forEach(it => {
    const cx = W * (-0.05 + it.x * 1.1);
    const base = horizon + Math.pow(it.z, 1.6) * (H - horizon);
    const h = (H * 0.06 + it.s * H * 0.20) * (0.3 + it.z * 1.1);
    const w = h * 0.30;
    const col = shade(p.hues[it.z > 0.5 ? 0 : 2], -55 + it.z * 70);
    s += `<rect x="${R(cx - w * 0.09)}" y="${R(base - h * 0.34)}" width="${R(w * 0.18)}" height="${R(h * 0.34)}" fill="${shade(col, -40)}"/>`;
    for (let k = 0; k < 3; k++) {
      const ky = base - h * (0.30 + k * 0.24), kw = w * (1 - k * 0.24), kh = h * 0.36;
      s += `<polygon points="${R(cx)},${R(ky - kh)} ${R(cx + kw)},${R(ky)} ${R(cx - kw)},${R(ky)}" fill="${shade(col, k * 12)}"/>`;
    }
  });
  return s;
}

function castle(a, W, H, horizon) {
  const p = a.palette;
  const cx = W * 0.5, base = horizon + (H - horizon) * 0.30;
  const u = H * 0.05;
  const col = shade(p.bg[1], 34), dark = shade(p.bg[1], 8), lite = shade(p.bg[1], 58);
  let s = `<g>`;
  s += `<ellipse cx="${R(cx)}" cy="${R(base + u * 0.3)}" rx="${R(u * 9)}" ry="${R(u * 0.9)}" fill="#000" opacity="0.5" filter="url(#soft)"/>`;
  // corps principal
  s += `<polygon points="${R(cx - u * 5)},${R(base)} ${R(cx - u * 5)},${R(base - u * 4.2)} ${R(cx + u * 5)},${R(base - u * 4.2)} ${R(cx + u * 5)},${R(base)}" fill="${col}"/>`;
  s += `<polygon points="${R(cx + u * 5)},${R(base - u * 4.2)} ${R(cx + u * 6.2)},${R(base - u * 4.9)} ${R(cx + u * 6.2)},${R(base - u * 0.7)} ${R(cx + u * 5)},${R(base)}" fill="${dark}"/>`;
  // tours
  [-6.2, -3.2, 3.2, 6.2].forEach((off, i) => {
    const tx = cx + u * off, th = u * (6.4 + (i % 2) * 1.6), tw = u * 1.25;
    s += `<polygon points="${R(tx - tw)},${R(base)} ${R(tx - tw)},${R(base - th)} ${R(tx + tw)},${R(base - th)} ${R(tx + tw)},${R(base)}" fill="${i % 2 ? col : lite}"/>`;
    s += `<polygon points="${R(tx + tw)},${R(base - th)} ${R(tx + tw * 1.4)},${R(base - th - u * 0.3)} ${R(tx + tw * 1.4)},${R(base - u * 0.3)} ${R(tx + tw)},${R(base)}" fill="${dark}"/>`;
    s += `<polygon points="${R(tx - tw * 1.5)},${R(base - th)} ${R(tx)},${R(base - th - u * 2.3)} ${R(tx + tw * 1.5)},${R(base - th)}" fill="${p.hues[i % p.hues.length]}" opacity="0.9"/>`;
    s += `<rect x="${R(tx - tw * 0.30)}" y="${R(base - th * 0.62)}" width="${R(tw * 0.6)}" height="${R(u * 0.85)}" rx="${R(tw * 0.3)}" fill="${p.glow}" opacity="0.9" filter="url(#glow)"/>`;
  });
  // porte
  s += `<path d="M ${R(cx - u * 1.15)} ${R(base)} L ${R(cx - u * 1.15)} ${R(base - u * 1.7)} Q ${R(cx)} ${R(base - u * 3.0)} ${R(cx + u * 1.15)} ${R(base - u * 1.7)} L ${R(cx + u * 1.15)} ${R(base)} Z" fill="${shade(dark, -22)}"/>`;
  s += `<path d="M ${R(cx - u * 1.15)} ${R(base)} L ${R(cx - u * 1.15)} ${R(base - u * 1.7)} Q ${R(cx)} ${R(base - u * 3.0)} ${R(cx + u * 1.15)} ${R(base - u * 1.7)} L ${R(cx + u * 1.15)} ${R(base)} Z" fill="${p.glow}" opacity="0.28" filter="url(#glow)"/>`;
  // créneaux
  for (let i = -4; i <= 4; i++)
    s += `<rect x="${R(cx + i * u * 1.1 - u * 0.34)}" y="${R(base - u * 4.85)}" width="${R(u * 0.68)}" height="${R(u * 0.68)}" fill="${lite}"/>`;
  s += `</g>`;
  return s;
}

function carScene(a, W, H, horizon) {
  const p = a.palette;
  const cx = W * 0.5, base = horizon + (H - horizon) * 0.60;
  const u = H * 0.035;
  const body = p.hues[0], dark = shade(body, -60), lite = shade(body, 55);
  let s = `<g>`;
  s += `<ellipse cx="${R(cx)}" cy="${R(base + u * 0.5)}" rx="${R(u * 9)}" ry="${R(u * 1.1)}" fill="#000" opacity="0.55" filter="url(#soft)"/>`;
  s += `<ellipse cx="${R(cx)}" cy="${R(base - u * 1.4)}" rx="${R(u * 11)}" ry="${R(u * 3.4)}" fill="${p.glow}" opacity="0.14" filter="url(#soft)"/>`;
  s += `<path d="M ${R(cx - u * 8)} ${R(base)} L ${R(cx - u * 7.2)} ${R(base - u * 1.5)} L ${R(cx - u * 4.2)} ${R(base - u * 2.0)} L ${R(cx - u * 2.2)} ${R(base - u * 3.5)} L ${R(cx + u * 2.4)} ${R(base - u * 3.6)} L ${R(cx + u * 4.6)} ${R(base - u * 2.0)} L ${R(cx + u * 7.6)} ${R(base - u * 1.6)} L ${R(cx + u * 8)} ${R(base)} Z" fill="${body}"/>`;
  s += `<path d="M ${R(cx - u * 2.0)} ${R(base - u * 2.1)} L ${R(cx - u * 0.6)} ${R(base - u * 3.3)} L ${R(cx + u * 2.2)} ${R(base - u * 3.35)} L ${R(cx + u * 3.9)} ${R(base - u * 2.1)} Z" fill="${shade(p.palette ? body : '#88ccff', 0)}" opacity="0.55"/>`;
  s += `<path d="M ${R(cx - u * 8)} ${R(base)} L ${R(cx - u * 7.2)} ${R(base - u * 1.5)} L ${R(cx + u * 7.6)} ${R(base - u * 1.6)} L ${R(cx + u * 8)} ${R(base)} Z" fill="${dark}" opacity="0.35"/>`;
  s += `<path d="M ${R(cx - u * 7.2)} ${R(base - u * 1.5)} L ${R(cx - u * 4.2)} ${R(base - u * 2.0)} L ${R(cx + u * 4.6)} ${R(base - u * 2.0)} L ${R(cx + u * 7.6)} ${R(base - u * 1.6)}" fill="none" stroke="${lite}" stroke-width="${R(u * 0.16)}" opacity="0.8"/>`;
  [-4.8, 4.6].forEach(off => {
    const wx = cx + u * off;
    s += `<circle cx="${R(wx)}" cy="${R(base - u * 0.15)}" r="${R(u * 1.55)}" fill="#0b0b0f"/>`;
    s += `<circle cx="${R(wx)}" cy="${R(base - u * 0.15)}" r="${R(u * 0.82)}" fill="${shade(p.bg[1], 55)}"/>`;
    s += `<circle cx="${R(wx)}" cy="${R(base - u * 0.15)}" r="${R(u * 0.30)}" fill="${lite}"/>`;
  });
  s += `<ellipse cx="${R(cx + u * 7.7)}" cy="${R(base - u * 1.25)}" rx="${R(u * 0.7)}" ry="${R(u * 0.3)}" fill="#fff" filter="url(#glow)"/>`;
  s += `<ellipse cx="${R(cx - u * 7.4)}" cy="${R(base - u * 1.2)}" rx="${R(u * 0.5)}" ry="${R(u * 0.26)}" fill="${p.hues[2]}" filter="url(#glow)"/>`;
  s += `</g>`;
  return s;
}

function portraitScene(a, W, H) {
  const p = a.palette;
  const cx = W * 0.5, cy = H * 0.52, u = H * 0.16;
  const skin = shade(p.hues[0], 30), dark = shade(p.hues[0], -50), lite = shade(p.hues[0], 80);
  let s = `<g>`;
  s += `<ellipse cx="${R(cx)}" cy="${R(cy)}" rx="${R(u * 3.2)}" ry="${R(u * 3.4)}" fill="${p.glow}" opacity="0.14" filter="url(#soft)"/>`;
  // épaules
  s += `<path d="M ${R(cx - u * 2.6)} ${H} Q ${R(cx - u * 2.3)} ${R(cy + u * 1.5)} ${R(cx)} ${R(cy + u * 1.35)} Q ${R(cx + u * 2.3)} ${R(cy + u * 1.5)} ${R(cx + u * 2.6)} ${H} Z" fill="${shade(p.bg[1], 30)}"/>`;
  // cou
  s += `<rect x="${R(cx - u * 0.34)}" y="${R(cy + u * 0.55)}" width="${R(u * 0.68)}" height="${R(u * 0.9)}" fill="${shade(skin, -34)}"/>`;
  // tête low-poly
  const face = [[0,-1.32],[0.62,-1.12],[0.86,-0.5],[0.80,0.22],[0.50,0.86],[0,1.16],[-0.50,0.86],[-0.80,0.22],[-0.86,-0.5],[-0.62,-1.12]]
    .map(([x, y]) => `${R(cx + x * u)},${R(cy + y * u)}`).join(' ');
  s += `<polygon points="${face}" fill="${skin}"/>`;
  s += `<polygon points="${face}" fill="url(#rim)" opacity="0.5"/>`;
  s += `<polygon points="${R(cx)},${R(cy - u * 1.32)} ${R(cx + 0.86 * u)},${R(cy - u * 0.5)} ${R(cx + 0.5 * u)},${R(cy + u * 0.86)} ${R(cx)},${R(cy + u * 1.16)}" fill="${dark}" opacity="0.30"/>`;
  // cheveux / casque
  s += `<path d="M ${R(cx - u * 0.90)} ${R(cy - u * 0.42)} Q ${R(cx - u * 0.95)} ${R(cy - u * 1.6)} ${R(cx)} ${R(cy - u * 1.48)} Q ${R(cx + u * 0.95)} ${R(cy - u * 1.6)} ${R(cx + u * 0.90)} ${R(cy - u * 0.42)} Q ${R(cx + u * 0.5)} ${R(cy - u * 0.95)} ${R(cx)} ${R(cy - u * 0.92)} Q ${R(cx - u * 0.5)} ${R(cy - u * 0.95)} ${R(cx - u * 0.90)} ${R(cy - u * 0.42)} Z" fill="${shade(p.hues[1], -45)}"/>`;
  // yeux
  [-0.36, 0.36].forEach(o => {
    s += `<ellipse cx="${R(cx + o * u)}" cy="${R(cy - u * 0.18)}" rx="${R(u * 0.17)}" ry="${R(u * 0.09)}" fill="#0c0c14"/>`;
    s += `<circle cx="${R(cx + o * u)}" cy="${R(cy - u * 0.18)}" r="${R(u * 0.062)}" fill="${p.hues[1]}" filter="url(#glow)"/>`;
  });
  s += `<polygon points="${R(cx)},${R(cy - u * 0.10)} ${R(cx + u * 0.10)},${R(cy + u * 0.26)} ${R(cx - u * 0.10)},${R(cy + u * 0.26)}" fill="${shade(skin, -30)}" opacity="0.75"/>`;
  s += `<path d="M ${R(cx - u * 0.24)} ${R(cy + u * 0.55)} Q ${R(cx)} ${R(cy + u * 0.70)} ${R(cx + u * 0.24)} ${R(cy + u * 0.55)}" fill="none" stroke="${shade(skin, -55)}" stroke-width="${R(u * 0.045)}"/>`;
  s += `</g>`;
  return s;
}

function abstractScene(a, W, H) {
  const p = a.palette;
  const r = rng(a.seed ^ 0xab57);
  let s = '';
  const shapes = [];
  for (let i = 0; i < 16; i++) shapes.push({ x: r(), y: r(), z: r(), t: Math.floor(r() * 3), c: Math.floor(r() * p.hues.length), rot: r() * 360, s: 0.3 + r() });
  shapes.sort((x, y) => x.z - y.z);
  shapes.forEach(it => {
    const cx = W * (0.05 + it.x * 0.9), cy = H * (0.10 + it.y * 0.80);
    const sz = (W * 0.03 + it.s * W * 0.11) * (0.35 + it.z);
    const col = p.hues[it.c];
    const f = it.z > 0.7 ? '' : ` filter="url(#dof${it.z > 0.4 ? 1 : 2})"`;
    s += `<g${f} transform="rotate(${R(it.rot)} ${R(cx)} ${R(cy)})">`;
    s += `<ellipse cx="${R(cx)}" cy="${R(cy)}" rx="${R(sz * 2.1)}" ry="${R(sz * 2.1)}" fill="${col}" opacity="0.11" filter="url(#soft)"/>`;
    if (it.t === 0) { // cube isométrique
      const h = sz;
      s += `<polygon points="${R(cx)},${R(cy - h)} ${R(cx + h * 0.87)},${R(cy - h * 0.5)} ${R(cx)},${R(cy)} ${R(cx - h * 0.87)},${R(cy - h * 0.5)}" fill="${shade(col, 55)}"/>`;
      s += `<polygon points="${R(cx - h * 0.87)},${R(cy - h * 0.5)} ${R(cx)},${R(cy)} ${R(cx)},${R(cy + h)} ${R(cx - h * 0.87)},${R(cy + h * 0.5)}" fill="${shade(col, -25)}"/>`;
      s += `<polygon points="${R(cx + h * 0.87)},${R(cy - h * 0.5)} ${R(cx)},${R(cy)} ${R(cx)},${R(cy + h)} ${R(cx + h * 0.87)},${R(cy + h * 0.5)}" fill="${shade(col, -55)}"/>`;
    } else if (it.t === 1) { // sphère
      s += `<circle cx="${R(cx)}" cy="${R(cy)}" r="${R(sz)}" fill="${shade(col, -20)}"/>`;
      s += `<circle cx="${R(cx)}" cy="${R(cy)}" r="${R(sz)}" fill="url(#sphere)"/>`;
    } else { // tore / anneau
      s += `<ellipse cx="${R(cx)}" cy="${R(cy)}" rx="${R(sz)}" ry="${R(sz * 0.38)}" fill="none" stroke="${col}" stroke-width="${R(sz * 0.26)}"/>`;
      s += `<ellipse cx="${R(cx)}" cy="${R(cy)}" rx="${R(sz)}" ry="${R(sz * 0.38)}" fill="none" stroke="${shade(col, 80)}" stroke-width="${R(sz * 0.07)}" opacity="0.75"/>`;
    }
    s += `</g>`;
  });
  return s;
}

function atmosphere(a, W, H) {
  const p = a.palette;
  const r = rng(a.seed ^ 0xa7d0);
  let s = '';
  if (a.fog) for (let i = 0; i < 8; i++) {
    const y = R(H * (0.42 + r() * 0.5));
    s += `<ellipse cx="${R(r() * W)}" cy="${y}" rx="${R(W * (0.18 + r() * 0.35))}" ry="${R(H * (0.03 + r() * 0.06))}" fill="${shade(p.bg[1], 45)}" opacity="${R(0.10 + r() * 0.16)}" filter="url(#soft)"/>`;
  }
  if (a.rain) for (let i = 0; i < 180; i++) {
    const x = R(r() * W), y = R(r() * H), l = R(H * 0.02 + r() * H * 0.03);
    s += `<line x1="${x}" y1="${y}" x2="${R(x - l * 0.24)}" y2="${R(y + l)}" stroke="${p.hues[1]}" stroke-width="1" opacity="${R(0.14 + r() * 0.30)}"/>`;
  }
  if (a.snow) for (let i = 0; i < 160; i++)
    s += `<circle cx="${R(r() * W)}" cy="${R(r() * H)}" r="${R(1 + r() * 3.2)}" fill="#fff" opacity="${R(0.25 + r() * 0.55)}"/>`;
  // particules lumineuses
  if (a.glow) for (let i = 0; i < 70; i++) {
    const rad = R(1 + r() * 4);
    s += `<circle cx="${R(r() * W)}" cy="${R(r() * H)}" r="${rad}" fill="${p.hues[Math.floor(r() * p.hues.length)]}" opacity="${R(0.20 + r() * 0.55)}" filter="url(#glow)"/>`;
  }
  return s;
}

/* ---------- assembleur principal ---------- */

function renderSVG(prompt, opts = {}) {
  const W = opts.width || 3840, H = opts.height || 2160;
  const a = analyze(prompt);
  const p = a.palette;
  const horizon = H * (a.aerial ? 0.34 : a.closeup ? 0.62 : 0.52);

  const defs = `
<defs>
  <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${shade(p.bg[0], -8)}"/>
    <stop offset="45%" stop-color="${p.sky}"/>
    <stop offset="100%" stop-color="${p.bg[1]}"/>
  </linearGradient>
  <linearGradient id="ground" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${shade(p.bg[1], -18)}"/>
    <stop offset="100%" stop-color="${shade(p.bg[0], 6)}"/>
  </linearGradient>
  <linearGradient id="water" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${shade(p.bg[1], 12)}"/>
    <stop offset="100%" stop-color="${shade(p.bg[0], -4)}"/>
  </linearGradient>
  <linearGradient id="rim" x1="0" y1="0" x2="1" y2="1">
    <stop offset="0%" stop-color="#ffffff" stop-opacity="0.42"/>
    <stop offset="48%" stop-color="#ffffff" stop-opacity="0"/>
    <stop offset="100%" stop-color="${p.glow}" stop-opacity="0.36"/>
  </linearGradient>
  <radialGradient id="sphere" cx="32%" cy="28%" r="78%">
    <stop offset="0%" stop-color="#ffffff" stop-opacity="0.62"/>
    <stop offset="45%" stop-color="#ffffff" stop-opacity="0.08"/>
    <stop offset="100%" stop-color="#000000" stop-opacity="0.55"/>
  </radialGradient>
  <radialGradient id="vig" cx="50%" cy="46%" r="76%">
    <stop offset="55%" stop-color="#000" stop-opacity="0"/>
    <stop offset="100%" stop-color="#000" stop-opacity="0.72"/>
  </radialGradient>
  <filter id="glow" x="-60%" y="-60%" width="220%" height="220%">
    <feGaussianBlur stdDeviation="${R(W * 0.0035)}" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="soft" x="-70%" y="-70%" width="240%" height="240%">
    <feGaussianBlur stdDeviation="${R(W * 0.012)}"/>
  </filter>
  <filter id="dof0"><feGaussianBlur stdDeviation="0"/></filter>
  <filter id="dof1"><feGaussianBlur stdDeviation="${R(W * 0.0016)}"/></filter>
  <filter id="dof2"><feGaussianBlur stdDeviation="${R(W * 0.0038)}"/></filter>
  <filter id="grain">
    <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="3" result="n"/>
    <feColorMatrix in="n" type="saturate" values="0"/>
    <feComponentTransfer><feFuncA type="linear" slope="0.055"/></feComponentTransfer>
  </filter>
</defs>`;

  const sky = skyLayer(a, W, H);
  let body = '';

  switch (a.subject) {
    case 'fox':
      body = mountains(a, W, H, horizon) + groundGrid(a, W, H, horizon) + trees(a, W, H, horizon, 0.42) + foxSilhouette(a, W, H, horizon);
      break;
    case 'city':
      body = mountains(a, W, H, horizon) + groundGrid(a, W, H, horizon) + cityScape(a, W, H, horizon);
      break;
    case 'mountain':
      body = mountains(a, W, H, horizon) + waterPlane(a, W, H, horizon + H * 0.10);
      break;
    case 'space':
      body = planets(a, W, H) + crystals(a, W, H, horizon + H * 0.15);
      break;
    case 'ocean':
      body = mountains(a, W, H, horizon * 0.96) + waterPlane(a, W, H, horizon);
      break;
    case 'forest':
      body = mountains(a, W, H, horizon) + trees(a, W, H, horizon);
      break;
    case 'portrait':
      body = groundGrid(a, W, H, horizon) + portraitScene(a, W, H);
      break;
    case 'car':
      body = groundGrid(a, W, H, horizon) + cityScape(a, W, H, horizon) + carScene(a, W, H, horizon);
      break;
    case 'castle':
      body = mountains(a, W, H, horizon) + groundGrid(a, W, H, horizon) + castle(a, W, H, horizon);
      break;
    default:
      body = groundGrid(a, W, H, horizon) + abstractScene(a, W, H);
  }

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
${defs}
${sky.svg}
${body}
${atmosphere(a, W, H)}
<rect width="${W}" height="${H}" fill="url(#vig)"/>
<rect width="${W}" height="${H}" filter="url(#grain)" opacity="0.5"/>
</svg>`;

  return {
    svg,
    meta: {
      palette: p.name,
      subject: a.subject,
      resolution: `${W}×${H}`,
      seed: a.seed,
      effects: [a.fog && 'brume', a.rain && 'pluie', a.snow && 'neige', a.stars && 'étoiles', a.glow && 'éclairage volumétrique'].filter(Boolean)
    }
  };
}

module.exports = { renderSVG, shade };

});

__def("webgen", function(module, exports, __req){
/** Fox IA — générateur de sites web à partir d'un prompt. */
const { analyze, hash, rng } = __req('ai');

const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const TYPES = {
  restaurant: { k: ['restaurant', 'brasserie', 'bistro', 'pizzeria', 'cuisine', 'chef', 'menu', 'gastronom', 'cafe', 'bar'], label: 'Restaurant',
    sections: ['Notre carte', 'Le chef', 'Réserver'],
    items: [['Entrées', 'Produits de saison, travaillés au jour le jour.'], ['Plats', 'Cuisine de marché, cuissons justes.'], ['Desserts', 'Pâtisserie maison, sucre dosé.']] },
  portfolio: { k: ['portfolio', 'photograph', 'artiste', 'designer', 'graphiste', 'illustrat', 'book', 'creatif'], label: 'Portfolio',
    sections: ['Projets', 'À propos', 'Contact'],
    items: [['Direction artistique', 'Identité, image, cohérence.'], ['Photographie', 'Lumière naturelle, cadrages nets.'], ['Motion', 'Animation courte et impactante.']] },
  shop: { k: ['boutique', 'shop', 'ecommerce', 'e-commerce', 'vente', 'produit', 'magasin', 'store'], label: 'Boutique',
    sections: ['Nos produits', 'Livraison', 'Contact'],
    items: [['Nouveautés', 'La sélection du moment.'], ['Best-sellers', 'Ce que tout le monde reprend.'], ['Éditions limitées', 'Petites séries, vraies pièces.']] },
  saas: { k: ['saas', 'startup', 'app', 'logiciel', 'plateforme', 'outil', 'tech', 'application'], label: 'SaaS',
    sections: ['Fonctionnalités', 'Tarifs', 'Démarrer'],
    items: [['Rapide', 'Déploiement en quelques minutes.'], ['Sécurisé', 'Chiffrement et sauvegardes automatiques.'], ['Évolutif', 'De 10 à 10 millions d\'utilisateurs.']] },
  agency: { k: ['agence', 'agency', 'conseil', 'consultant', 'marketing', 'communication', 'studio'], label: 'Agence',
    sections: ['Services', 'Méthode', 'Parlons-en'],
    items: [['Stratégie', 'On pose le cap avant de courir.'], ['Création', 'Design, contenu, production.'], ['Diffusion', 'Le bon message, au bon endroit.']] },
  salon: { k: ['coiffure', 'salon', 'beaute', 'spa', 'esthetique', 'barbier', 'ongle', 'massage'], label: 'Salon',
    sections: ['Prestations', 'L\'équipe', 'Rendez-vous'],
    items: [['Coupe & couleur', 'Diagnostic personnalisé à chaque visite.'], ['Soins', 'Protocoles sur mesure.'], ['Événement', 'Mariages, shootings, cérémonies.']] },
  immo: { k: ['immobilier', 'immo', 'maison', 'appartement', 'agence immo', 'location', 'bien'], label: 'Immobilier',
    sections: ['Nos biens', 'Estimation', 'Contact'],
    items: [['Vente', 'Des biens vérifiés, des dossiers clairs.'], ['Location', 'Gestion complète et sereine.'], ['Estimation', 'Une valeur juste, argumentée.']] },
  event: { k: ['evenement', 'mariage', 'festival', 'concert', 'conference', 'seminaire', 'soiree'], label: 'Événement',
    sections: ['Programme', 'Intervenants', 'Billetterie'],
    items: [['Jour 1', 'Ouverture, keynote, ateliers.'], ['Jour 2', 'Tables rondes et démonstrations.'], ['Soirée', 'Networking et clôture.']] },
  sport: { k: ['sport', 'salle', 'fitness', 'coach', 'muscu', 'yoga', 'club', 'football', 'rugby'], label: 'Sport',
    sections: ['Nos cours', 'Coachs', 'Nous rejoindre'],
    items: [['Cours collectifs', 'Énergie de groupe, progression réelle.'], ['Coaching', 'Un programme rien que pour toi.'], ['Accès libre', 'Ouvert 7j/7 de 6h à 23h.']] },
  perso: { k: ['blog', 'personnel', 'cv', 'curriculum', 'freelance', 'developpeur'], label: 'Site personnel',
    sections: ['Parcours', 'Compétences', 'Me contacter'],
    items: [['Expérience', 'Des projets livrés, pas des promesses.'], ['Compétences', 'Techniques et humaines.'], ['Disponibilité', 'Ouvert aux missions.']] }
};

const THEMES = {
  neon:   { bg: '#07040f', bg2: '#120a26', card: '#170d2e', text: '#f4f0ff', dim: '#a99fc4', a: '#8b5cf6', b: '#22d3ee', font: "'Segoe UI',system-ui,sans-serif", radius: '20px' },
  gold:   { bg: '#0d0a04', bg2: '#1c1608', card: '#241c0a', text: '#fbf6e8', dim: '#c4b795', a: '#d4a017', b: '#f5d271', font: "Georgia,'Times New Roman',serif", radius: '4px' },
  ocean:  { bg: '#03121f', bg2: '#062639', card: '#082f47', text: '#eaf6ff', dim: '#93b8cf', a: '#0ea5e9', b: '#5eead4', font: "'Segoe UI',system-ui,sans-serif", radius: '16px' },
  forest: { bg: '#05130d', bg2: '#0a2418', card: '#0d2e1f', text: '#ecfdf5', dim: '#96c4ad', a: '#10b981', b: '#a3e635', font: "'Segoe UI',system-ui,sans-serif", radius: '14px' },
  sunset: { bg: '#170609', bg2: '#2c0c14', card: '#38101a', text: '#fff1eb', dim: '#d3a396', a: '#f97316', b: '#f43f5e', font: "'Segoe UI',system-ui,sans-serif", radius: '24px' },
  light:  { bg: '#ffffff', bg2: '#f4f6fb', card: '#ffffff', text: '#0f172a', dim: '#5b6478', a: '#4f46e5', b: '#0ea5e9', font: "'Segoe UI',system-ui,sans-serif", radius: '14px' },
  mono:   { bg: '#0a0a0a', bg2: '#131313', card: '#171717', text: '#fafafa', dim: '#9d9d9d', a: '#ffffff', b: '#a3a3a3', font: "'Helvetica Neue',Arial,sans-serif", radius: '0px' }
};

function pickType(m) {
  let best = 'agency', score = 0;
  for (const [k, v] of Object.entries(TYPES)) {
    const s = v.k.reduce((a, w) => a + (m.includes(w) ? 1 : 0), 0);
    if (s > score) { score = s; best = k; }
  }
  return best;
}
function pickTheme(m, fallback) {
  if (/clair|blanc|light|sobre|epure|minimal|propre/.test(m)) return 'light';
  if (/or |dore|gold|luxe|prestige|haut de gamme|chic|elegant/.test(m)) return 'gold';
  if (/bleu|mer|ocean|aqua|marin/.test(m)) return 'ocean';
  if (/vert|nature|bio|ecolo|foret/.test(m)) return 'forest';
  if (/orange|chaud|sunset|coucher|rouge|rose/.test(m)) return 'sunset';
  if (/noir et blanc|monochrome|gris|brut/.test(m)) return 'mono';
  if (/neon|violet|cyber|futur|tech|sombre|dark/.test(m)) return 'neon';
  return fallback;
}
function pickName(prompt) {
  const q = prompt.match(/["«“']([^"»”']{2,40})["»”']/);
  if (q) return q[1].trim();
  const ap = prompt.match(/(?:appel[ée]e?|nomm[ée]e?|au nom de|qui s'appelle)\s+([A-Za-zÀ-ÿ0-9' -]{2,32})/i);
  if (ap) return ap[1].trim().replace(/\s+(et|avec|pour|dans)$/i, '');
  const cap = prompt.match(/\b([A-ZÀ-Ý][a-zà-ÿ]{2,}(?:\s+[A-ZÀ-Ý][a-zà-ÿ]{2,})?)\b/);
  if (cap && !/^(Un|Une|Le|La|Les|Je|Site|Page|Web|Fox)$/i.test(cap[1])) return cap[1];
  return null;
}
function pickCity(m) {
  const cities = ['pau', 'paris', 'lyon', 'marseille', 'bordeaux', 'toulouse', 'lille', 'nantes', 'nice', 'biarritz', 'bayonne', 'tarbes', 'strasbourg', 'rennes', 'montpellier'];
  const f = cities.find(c => m.includes(c));
  return f ? f.charAt(0).toUpperCase() + f.slice(1) : null;
}

function generateSite(prompt) {
  const m = norm(prompt);
  const a = analyze(prompt);
  const r = rng(a.seed);
  const typeKey = pickType(m);
  const T = TYPES[typeKey];
  const themeKey = pickTheme(m, ({ restaurant: 'gold', portfolio: 'mono', shop: 'light', saas: 'neon', salon: 'gold', immo: 'light', sport: 'sunset', event: 'neon', agency: 'neon', perso: 'neon' })[typeKey] || 'neon');
  const th = THEMES[themeKey];
  const name = pickName(prompt) || ({ restaurant: 'La Table', portfolio: 'Studio', shop: 'Maison', saas: 'Nova', agency: 'Atelier', salon: 'Éclat', immo: 'Horizon', event: 'Rendez-vous', sport: 'Élan', perso: 'Moi' })[typeKey];
  const city = pickCity(m) || 'Pau';
  const tagline = ({
    restaurant: `Cuisine de saison, à ${city}.`,
    portfolio: `Création visuelle & direction artistique.`,
    shop: `Des pièces choisies, pas empilées.`,
    saas: `L'outil qui fait gagner du temps, vraiment.`,
    agency: `On transforme une intention en résultat.`,
    salon: `Prendre soin, avec exigence.`,
    immo: `Votre prochain chez-vous, à ${city}.`,
    event: `L'édition ${new Date().getFullYear()} arrive.`,
    sport: `Progresser, sans se mentir.`,
    perso: `Bienvenue. Voici ce que je fais.`
  })[typeKey];

  const dark = themeKey !== 'light';
  const heroSvg = encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="700"><defs><radialGradient id="g" cx="50%" cy="40%"><stop offset="0%" stop-color="${th.a}" stop-opacity="0.55"/><stop offset="100%" stop-color="${th.bg}" stop-opacity="0"/></radialGradient></defs><rect width="1200" height="700" fill="${th.bg}"/><circle cx="600" cy="300" r="420" fill="url(#g)"/></svg>`);

  const html = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(name)} — ${T.label}</title>
<meta name="description" content="${esc(tagline)}">
<style>
*{margin:0;padding:0;box-sizing:border-box}
:root{--bg:${th.bg};--bg2:${th.bg2};--card:${th.card};--text:${th.text};--dim:${th.dim};--a:${th.a};--b:${th.b};--r:${th.radius}}
html{scroll-behavior:smooth}
body{font-family:${th.font};background:var(--bg);color:var(--text);line-height:1.65;overflow-x:hidden}
.wrap{max-width:1140px;margin:0 auto;padding:0 24px}
header{position:fixed;top:0;left:0;right:0;z-index:50;backdrop-filter:blur(14px);background:${dark ? 'rgba(0,0,0,.45)' : 'rgba(255,255,255,.8)'};border-bottom:1px solid ${dark ? 'rgba(255,255,255,.08)' : 'rgba(0,0,0,.08)'}}
nav{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;max-width:1140px;margin:0 auto}
.logo{font-size:1.35rem;font-weight:800;letter-spacing:-.5px;background:linear-gradient(135deg,var(--a),var(--b));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
nav ul{display:flex;gap:28px;list-style:none}
nav a{color:var(--dim);text-decoration:none;font-size:.94rem;font-weight:500;transition:.2s}
nav a:hover{color:var(--text)}
.btn{display:inline-block;padding:13px 30px;border-radius:var(--r);background:linear-gradient(135deg,var(--a),var(--b));color:#fff;text-decoration:none;font-weight:700;border:none;cursor:pointer;font-size:.96rem;transition:.25s;box-shadow:0 8px 28px -8px var(--a)}
.btn:hover{transform:translateY(-2px);box-shadow:0 14px 36px -8px var(--a)}
.btn.ghost{background:transparent;border:1.5px solid var(--a);color:var(--a);box-shadow:none}
.hero{min-height:100vh;display:flex;align-items:center;position:relative;background:url("data:image/svg+xml,${heroSvg}") center/cover no-repeat,var(--bg)}
.hero::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 100%,transparent 40%,var(--bg) 90%)}
.hero .wrap{position:relative;z-index:2;text-align:center}
.badge{display:inline-block;padding:7px 18px;border-radius:99px;border:1px solid var(--a);color:var(--b);font-size:.8rem;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:28px}
h1{font-size:clamp(2.6rem,7.5vw,5.2rem);font-weight:900;line-height:1.03;letter-spacing:-2.5px;margin-bottom:22px}
h1 span{background:linear-gradient(135deg,var(--a),var(--b));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.lead{font-size:clamp(1.05rem,2.2vw,1.35rem);color:var(--dim);max-width:640px;margin:0 auto 40px}
.cta{display:flex;gap:16px;justify-content:center;flex-wrap:wrap}
section{padding:110px 0}
.alt{background:var(--bg2)}
h2{font-size:clamp(1.9rem,4.5vw,3rem);font-weight:800;letter-spacing:-1.2px;margin-bottom:16px;text-align:center}
.sub{text-align:center;color:var(--dim);max-width:600px;margin:0 auto 60px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:26px}
.card{background:var(--card);border:1px solid ${dark ? 'rgba(255,255,255,.09)' : 'rgba(0,0,0,.07)'};border-radius:var(--r);padding:36px 30px;transition:.3s}
.card:hover{transform:translateY(-8px);border-color:var(--a);box-shadow:0 22px 50px -20px var(--a)}
.ico{width:54px;height:54px;border-radius:14px;background:linear-gradient(135deg,var(--a),var(--b));display:flex;align-items:center;justify-content:center;font-size:1.6rem;margin-bottom:20px}
.card h3{font-size:1.25rem;margin-bottom:10px;font-weight:700}
.card p{color:var(--dim);font-size:.97rem}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:32px;text-align:center;margin-top:20px}
.stat b{display:block;font-size:2.8rem;font-weight:900;background:linear-gradient(135deg,var(--a),var(--b));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.stat span{color:var(--dim);font-size:.9rem;text-transform:uppercase;letter-spacing:1.2px}
form{max-width:560px;margin:0 auto;display:grid;gap:16px}
input,textarea{width:100%;padding:15px 18px;border-radius:var(--r);border:1px solid ${dark ? 'rgba(255,255,255,.14)' : 'rgba(0,0,0,.14)'};background:${dark ? 'rgba(255,255,255,.04)' : '#fff'};color:var(--text);font-family:inherit;font-size:1rem}
input:focus,textarea:focus{outline:none;border-color:var(--a)}
textarea{min-height:130px;resize:vertical}
footer{padding:54px 0 34px;border-top:1px solid ${dark ? 'rgba(255,255,255,.08)' : 'rgba(0,0,0,.08)'};text-align:center;color:var(--dim);font-size:.9rem}
footer .logo{margin-bottom:14px;font-size:1.15rem}
.reveal{opacity:0;transform:translateY(34px);transition:.75s cubic-bezier(.2,.7,.2,1)}
.reveal.in{opacity:1;transform:none}
@media(max-width:760px){nav ul{display:none}section{padding:74px 0}}
</style>
</head>
<body>
<header><nav>
  <div class="logo">${esc(name)}</div>
  <ul>${T.sections.map((s, i) => `<li><a href="#s${i}">${esc(s)}</a></li>`).join('')}</ul>
  <a href="#s2" class="btn" style="padding:10px 22px">Contact</a>
</nav></header>

<div class="hero"><div class="wrap">
  <div class="badge">${esc(T.label)}${city ? ' · ' + esc(city) : ''}</div>
  <h1>${esc(name)}<br><span>${esc(tagline)}</span></h1>
  <p class="lead">${esc(prompt.trim().slice(0, 180))}</p>
  <div class="cta"><a href="#s0" class="btn">Découvrir</a><a href="#s2" class="btn ghost">Nous contacter</a></div>
</div></div>

<section id="s0"><div class="wrap">
  <h2 class="reveal">${esc(T.sections[0])}</h2>
  <p class="sub reveal">Ce que nous faisons, et comment nous le faisons bien.</p>
  <div class="grid">
    ${T.items.map(([t, d], i) => `<div class="card reveal"><div class="ico">${['◆', '●', '▲'][i]}</div><h3>${esc(t)}</h3><p>${esc(d)}</p></div>`).join('\n    ')}
  </div>
</div></section>

<section id="s1" class="alt"><div class="wrap">
  <h2 class="reveal">${esc(T.sections[1])}</h2>
  <p class="sub reveal">Des chiffres, pas des slogans.</p>
  <div class="stats reveal">
    <div class="stat"><b>${Math.floor(r() * 12) + 4}</b><span>Années</span></div>
    <div class="stat"><b>${Math.floor(r() * 400) + 120}</b><span>Clients</span></div>
    <div class="stat"><b>${(4 + r()).toFixed(1)}</b><span>Note moyenne</span></div>
    <div class="stat"><b>${Math.floor(r() * 40) + 20}</b><span>Projets / an</span></div>
  </div>
</div></section>

<section id="s2"><div class="wrap">
  <h2 class="reveal">${esc(T.sections[2])}</h2>
  <p class="sub reveal">Écrivez-nous, on répond sous 24 h.</p>
  <form class="reveal" onsubmit="event.preventDefault();this.innerHTML='<p style=\\'text-align:center;padding:40px\\'>Merci ! Votre message est parti. ✓</p>'">
    <input type="text" placeholder="Votre nom" required>
    <input type="email" placeholder="Votre email" required>
    <textarea placeholder="Votre message" required></textarea>
    <button type="submit" class="btn">Envoyer</button>
  </form>
</div></section>

<footer><div class="wrap">
  <div class="logo">${esc(name)}</div>
  <p>${esc(tagline)}${city ? ' — ' + esc(city) + ', France' : ''}</p>
  <p style="margin-top:14px;opacity:.65">© ${new Date().getFullYear()} ${esc(name)} · Site généré par Fox IA 🦊</p>
</div></footer>

<script>
const io=new IntersectionObserver(e=>e.forEach(x=>x.isIntersecting&&x.target.classList.add('in')),{threshold:.12});
document.querySelectorAll('.reveal').forEach((el,i)=>{el.style.transitionDelay=(i%3*90)+'ms';io.observe(el)});
</script>
</body>
</html>`;

  return { html, meta: { type: T.label, theme: themeKey, name, city, sections: T.sections } };
}

module.exports = { generateSite };

});

__def("mailer", function(module, exports, __req){
/**
 * Fox IA — envoi d'emails (réinitialisation de mot de passe).
 *
 * Optionnel : si aucun SMTP n'est configuré, l'application reste 100 % fonctionnelle
 * et affiche le lien de réinitialisation directement à l'écran.
 *
 * Pour activer l'envoi réel (gratuit avec Gmail) :
 *   SMTP_HOST=smtp.gmail.com
 *   SMTP_PORT=587
 *   SMTP_USER=ton.adresse@gmail.com
 *   SMTP_PASS=mot-de-passe-application-16-caracteres
 *   SMTP_FROM=Fox IA <ton.adresse@gmail.com>
 */
let nodemailer = null;
try { nodemailer = require('nodemailer'); } catch (e) {}

const HOST = process.env.SMTP_HOST || '';
const USER = process.env.SMTP_USER || '';
const PASS = process.env.SMTP_PASS || '';
const PORT = Number(process.env.SMTP_PORT || 587);
const FROM = process.env.SMTP_FROM || (USER ? `Fox IA <${USER}>` : '');

const configured = () => Boolean(nodemailer && HOST && USER && PASS);

let transport = null;
function getTransport() {
  if (!configured()) return null;
  if (!transport) transport = nodemailer.createTransport({
    host: HOST, port: PORT, secure: PORT === 465, auth: { user: USER, pass: PASS }
  });
  return transport;
}

function template(pseudo, link) {
  return `<!DOCTYPE html><html lang="fr"><body style="margin:0;padding:0;background:#07040f;font-family:'Segoe UI',system-ui,sans-serif">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#07040f;padding:40px 16px">
    <tr><td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#110726;border:1px solid rgba(168,140,255,.22);border-radius:22px;overflow:hidden">
        <tr><td style="padding:36px 34px;text-align:center">
          <div style="width:70px;height:70px;margin:0 auto 18px;border-radius:20px;background:linear-gradient(135deg,#8b5cf6,#22d3ee);line-height:70px;font-size:36px">🦊</div>
          <h1 style="margin:0 0 6px;font-size:26px;color:#f3efff;letter-spacing:-.6px">Fox IA</h1>
          <p style="margin:0;color:#a498c9;font-size:14px">Réinitialisation de mot de passe</p>
        </td></tr>
        <tr><td style="padding:0 34px 30px">
          <p style="color:#f3efff;font-size:15px;line-height:1.7;margin:0 0 18px">Bonjour <b>${pseudo}</b>,</p>
          <p style="color:#a498c9;font-size:15px;line-height:1.7;margin:0 0 26px">
            Tu as demandé à réinitialiser ton mot de passe. Clique sur le bouton ci-dessous pour en choisir un nouveau.
            Ce lien est valable <b style="color:#22d3ee">1 heure</b>.
          </p>
          <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 26px">
            <tr><td style="border-radius:13px;background:linear-gradient(135deg,#8b5cf6,#22d3ee)">
              <a href="${link}" style="display:inline-block;padding:15px 38px;color:#fff;text-decoration:none;font-weight:700;font-size:15px">Choisir un nouveau mot de passe</a>
            </td></tr>
          </table>
          <p style="color:#7d729c;font-size:12.5px;line-height:1.6;margin:0 0 8px">Si le bouton ne fonctionne pas, copie ce lien dans ton navigateur :</p>
          <p style="margin:0;word-break:break-all"><a href="${link}" style="color:#22d3ee;font-size:12.5px">${link}</a></p>
          <hr style="border:none;border-top:1px solid rgba(168,140,255,.16);margin:26px 0 18px">
          <p style="color:#7d729c;font-size:12.5px;line-height:1.6;margin:0">
            Tu n'as rien demandé ? Ignore simplement cet email, ton mot de passe reste inchangé.
          </p>
        </td></tr>
      </table>
      <p style="color:#5c5478;font-size:12px;margin:20px 0 0">© ${new Date().getFullYear()} Fox IA 🦊</p>
    </td></tr>
  </table></body></html>`;
}

async function sendReset(to, pseudo, link) {
  const t = getTransport();
  if (!t) return { sent: false, reason: 'smtp_not_configured' };
  try {
    await t.sendMail({
      from: FROM, to,
      subject: '🦊 Fox IA — Réinitialise ton mot de passe',
      text: `Bonjour ${pseudo},\n\nPour choisir un nouveau mot de passe, ouvre ce lien (valable 1 heure) :\n${link}\n\nSi tu n'as rien demandé, ignore cet email.\n\n— Fox IA`,
      html: template(pseudo, link)
    });
    return { sent: true };
  } catch (e) {
    console.error('Envoi email échoué :', e.message);
    return { sent: false, reason: e.message };
  }
}

module.exports = { configured, sendReset };

});


/* ============ serveur ============ */
require('dotenv').config();
const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const cookieParser = require('cookie-parser');
const fetch = require('node-fetch');

const { q, init, getSetting, setSetting, log, PG, CI } = __req('db');
const ai = __req('ai');
const { renderSVG } = __req('render');
const { generateSite } = __req('webgen');
const mailer = __req('mailer');

const app = express();
const PORT = process.env.PORT || 3000;
const SECRET = process.env.JWT_SECRET || 'fox-ia-secret-change-me-in-production';
const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID || '';
const PROD = process.env.NODE_ENV === 'production';

app.use(express.json({ limit: '12mb' }));
app.use(cookieParser());
app.set('trust proxy', 1);

const GEN = path.join(require('os').tmpdir(), 'foxia-gen');
fs.mkdirSync(GEN, { recursive: true });

const wrap = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

/** Écrit un fichier généré sur le disque ET en base (le disque Render est éphémère). */
async function saveFile(name, content, mime) {
  try { fs.writeFileSync(path.join(GEN, name), content); } catch (e) {}
  try {
    await q.run('INSERT INTO files(name,mime,content) VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET content=excluded.content', [name, mime, content]);
  } catch (e) { console.error('saveFile:', e.message); }
}

/* ---------------- auth helpers ---------------- */
const sign = u => jwt.sign({ id: u.id, pseudo: u.pseudo, role: u.role }, SECRET, { expiresIn: '30d' });
const setCookie = (res, t) => res.cookie('foxia', t, {
  httpOnly: true, sameSite: 'lax', secure: PROD, maxAge: 30 * 24 * 3600 * 1000
});

const auth = wrap(async (req, res, next) => {
  const t = req.cookies.foxia || (req.headers.authorization || '').replace('Bearer ', '');
  if (!t) return res.status(401).json({ error: 'Non connecté' });
  let p;
  try { p = jwt.verify(t, SECRET); } catch { return res.status(401).json({ error: 'Session expirée' }); }
  const u = await q.get('SELECT id,pseudo,email,role,avatar,banned,credits,created_at FROM users WHERE id=?', [p.id]);
  if (!u) return res.status(401).json({ error: 'Compte introuvable' });
  if (u.banned) return res.status(403).json({ error: 'Compte suspendu' });
  req.user = u; next();
});
const admin = (req, res, next) => req.user.role === 'admin' ? next() : res.status(403).json({ error: "Réservé à l'administrateur" });
const isFirst = async () => Number((await q.get('SELECT COUNT(*) AS c FROM users')).c) === 0;

async function createUser({ pseudo, email, password, provider = 'email', avatar = null }) {
  const role = (await isFirst()) ? 'admin' : 'user';
  const hash = password ? bcrypt.hashSync(password, 10) : null;
  const info = await q.run(
    'INSERT INTO users(pseudo,email,password_hash,provider,avatar,role) VALUES(?,?,?,?,?,?)',
    [pseudo, email.toLowerCase(), hash, provider, avatar, role]);
  await log('signup', `${pseudo} <${email}> via ${provider} → ${role}`);
  const id = info.lastInsertRowid ?? (await q.get('SELECT id FROM users WHERE email=?', [email.toLowerCase()])).id;
  return q.get('SELECT id,pseudo,email,role,avatar,credits,created_at FROM users WHERE id=?', [id]);
}

/* ---------------- santé & config ---------------- */
app.get('/api/health', (req, res) => res.json({ ok: true, db: PG ? 'postgres' : 'sqlite', ts: Date.now() }));

app.get('/api/config', wrap(async (req, res) => {
  res.json({
    siteName: await getSetting('site_name', 'Fox IA'),
    announcement: await getSetting('announcement', ''),
    maintenance: (await getSetting('maintenance')) === '1',
    signupsOpen: (await getSetting('signups_open')) === '1',
    firstUser: await isFirst(),
    googleClientId: GOOGLE_CLIENT_ID,
    aiConnected: ai.connected(),
    mailConfigured: mailer.configured(),
    userCount: Number((await q.get('SELECT COUNT(*) AS c FROM users')).c)
  });
}));

/* ---------------- inscription / connexion ---------------- */
app.post('/api/auth/register', wrap(async (req, res) => {
  let { pseudo, email, password } = req.body || {};
  pseudo = (pseudo || '').trim(); email = (email || '').trim().toLowerCase();
  if (!/^[a-zA-Z0-9_\-. ]{3,24}$/.test(pseudo)) return res.status(400).json({ error: 'Pseudo : 3 à 24 caractères (lettres, chiffres, _ - .)' });
  if (!/^\S+@\S+\.\S+$/.test(email)) return res.status(400).json({ error: 'Email invalide' });
  if (!password || password.length < 6) return res.status(400).json({ error: 'Mot de passe : 6 caractères minimum' });
  const first = await isFirst();
  if (!first && (await getSetting('signups_open')) !== '1') return res.status(403).json({ error: 'Les inscriptions sont fermées' });
  if (await q.get(`SELECT 1 AS x FROM users WHERE ${CI('pseudo')}=${CI('?')}`, [pseudo])) return res.status(409).json({ error: 'Ce pseudo est déjà pris' });
  if (await q.get('SELECT 1 AS x FROM users WHERE email=?', [email])) return res.status(409).json({ error: 'Cet email a déjà un compte' });
  const u = await createUser({ pseudo, email, password });
  setCookie(res, sign(u));
  res.json({ user: u, firstAdmin: u.role === 'admin' });
}));

app.post('/api/auth/login', wrap(async (req, res) => {
  const { identifier, password } = req.body || {};
  const raw = (identifier || '').trim();
  const u = await q.get(`SELECT * FROM users WHERE email=? OR ${CI('pseudo')}=${CI('?')}`, [raw.toLowerCase(), raw]);
  if (!u || !u.password_hash || !bcrypt.compareSync(password || '', u.password_hash))
    return res.status(401).json({ error: 'Identifiants incorrects' });
  if (u.banned) return res.status(403).json({ error: 'Compte suspendu' });
  setCookie(res, sign(u));
  await log('login', u.pseudo);
  res.json({ user: { id: u.id, pseudo: u.pseudo, email: u.email, role: u.role, avatar: u.avatar, credits: u.credits } });
}));

app.post('/api/auth/google', wrap(async (req, res) => {
  const { credential, pseudo } = req.body || {};
  if (!credential) return res.status(400).json({ error: 'Jeton Google manquant' });
  const r = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(credential)}`);
  const p = await r.json();
  if (!p.email) return res.status(401).json({ error: 'Jeton Google invalide' });
  if (GOOGLE_CLIENT_ID && p.aud !== GOOGLE_CLIENT_ID) return res.status(401).json({ error: 'Jeton non destiné à ce site' });
  const email = p.email.toLowerCase();
  let u = await q.get('SELECT id,pseudo,email,role,avatar,banned,credits FROM users WHERE email=?', [email]);
  if (!u) {
    if (!(await isFirst()) && (await getSetting('signups_open')) !== '1') return res.status(403).json({ error: 'Les inscriptions sont fermées' });
    const base = (pseudo || p.name || email.split('@')[0]).replace(/[^a-zA-Z0-9_\-. ]/g, '').slice(0, 20) || 'Renard';
    let candidate = base, i = 1;
    while (await q.get(`SELECT 1 AS x FROM users WHERE ${CI('pseudo')}=${CI('?')}`, [candidate])) candidate = `${base}${++i}`;
    u = await createUser({ pseudo: candidate, email, provider: 'google', avatar: p.picture || null });
  }
  if (u.banned) return res.status(403).json({ error: 'Compte suspendu' });
  setCookie(res, sign(u));
  res.json({ user: u, firstAdmin: u.role === 'admin' });
}));

app.post('/api/auth/logout', (req, res) => { res.clearCookie('foxia'); res.json({ ok: true }); });
app.get('/api/me', auth, (req, res) => res.json({ user: req.user }));

/* ---------------- MOT DE PASSE OUBLIÉ ---------------- */

// 1) demander un lien de réinitialisation
app.post('/api/auth/forgot', wrap(async (req, res) => {
  const email = (req.body?.email || '').trim().toLowerCase();
  if (!/^\S+@\S+\.\S+$/.test(email)) return res.status(400).json({ error: 'Email invalide' });

  const u = await q.get('SELECT id,pseudo,email,provider FROM users WHERE email=?', [email]);
  // réponse identique dans tous les cas : on ne révèle pas si le compte existe
  const generic = { ok: true, message: "Si un compte existe avec cet email, un lien de réinitialisation vient d'être envoyé." };

  if (!u) { await log('forgot_unknown', email, 'warn'); return res.json(generic); }
  if (u.provider === 'google') {
    return res.json({ ok: true, google: true, message: "Ce compte utilise la connexion Google : reconnecte-toi avec le bouton Google, il n'y a pas de mot de passe à réinitialiser." });
  }

  const token = crypto.randomBytes(32).toString('hex');
  const hash = crypto.createHash('sha256').update(token).digest('hex');
  const exp = new Date(Date.now() + 60 * 60 * 1000).toISOString(); // 1 heure
  await q.run('UPDATE users SET reset_token=?, reset_expires=? WHERE id=?', [hash, exp, u.id]);

  const base = process.env.PUBLIC_URL || `${req.protocol}://${req.get('host')}`;
  const link = `${base}/?reset=${token}`;
  const sent = await mailer.sendReset(u.email, u.pseudo, link);
  await log('forgot', `${u.pseudo} — email ${sent.sent ? 'envoyé' : 'non configuré'}`);

  // Si aucun service d'email n'est configuré, on renvoie le lien directement
  // (utile en local et tant que l'admin n'a pas branché son SMTP).
  if (!sent.sent) return res.json({ ...generic, devLink: link, mailMissing: true });
  res.json(generic);
}));

// 2) vérifier la validité d'un jeton
app.get('/api/auth/reset/:token', wrap(async (req, res) => {
  const hash = crypto.createHash('sha256').update(req.params.token).digest('hex');
  const u = await q.get('SELECT id,pseudo,reset_expires FROM users WHERE reset_token=?', [hash]);
  if (!u || !u.reset_expires || new Date(u.reset_expires) < new Date())
    return res.status(400).json({ error: 'Lien invalide ou expiré. Demande un nouveau lien.' });
  res.json({ ok: true, pseudo: u.pseudo });
}));

// 3) définir le nouveau mot de passe
app.post('/api/auth/reset', wrap(async (req, res) => {
  const { token, password } = req.body || {};
  if (!password || password.length < 6) return res.status(400).json({ error: 'Mot de passe : 6 caractères minimum' });
  const hash = crypto.createHash('sha256').update(token || '').digest('hex');
  const u = await q.get('SELECT id,pseudo,email,role,avatar,credits,reset_expires FROM users WHERE reset_token=?', [hash]);
  if (!u || !u.reset_expires || new Date(u.reset_expires) < new Date())
    return res.status(400).json({ error: 'Lien invalide ou expiré. Demande un nouveau lien.' });
  await q.run('UPDATE users SET password_hash=?, reset_token=NULL, reset_expires=NULL WHERE id=?', [bcrypt.hashSync(password, 10), u.id]);
  await log('reset_done', u.pseudo);
  setCookie(res, sign(u));
  res.json({ ok: true, user: { id: u.id, pseudo: u.pseudo, email: u.email, role: u.role, avatar: u.avatar, credits: u.credits } });
}));

// 4) changer son mot de passe en étant connecté
app.post('/api/auth/change-password', auth, wrap(async (req, res) => {
  const { current, password } = req.body || {};
  if (!password || password.length < 6) return res.status(400).json({ error: 'Nouveau mot de passe : 6 caractères minimum' });
  const u = await q.get('SELECT * FROM users WHERE id=?', [req.user.id]);
  if (u.password_hash && !bcrypt.compareSync(current || '', u.password_hash))
    return res.status(401).json({ error: 'Mot de passe actuel incorrect' });
  await q.run('UPDATE users SET password_hash=? WHERE id=?', [bcrypt.hashSync(password, 10), u.id]);
  await log('password_change', u.pseudo);
  res.json({ ok: true });
}));

/* ---------------- chat ---------------- */
app.post('/api/chat', auth, wrap(async (req, res) => {
  const msg = (req.body?.message || '').trim();
  if (!msg) return res.status(400).json({ error: 'Message vide' });
  const hist = (await q.all('SELECT role,content FROM messages WHERE user_id=? ORDER BY id DESC LIMIT 12', [req.user.id])).reverse();
  await q.run('INSERT INTO messages(user_id,role,content) VALUES(?,?,?)', [req.user.id, 'user', msg]);
  const out = await ai.chat(hist, msg);
  await q.run('INSERT INTO messages(user_id,role,content) VALUES(?,?,?)', [req.user.id, 'assistant', out.text]);
  res.json({ reply: out.text, engine: out.engine });
}));
app.get('/api/chat/history', auth, wrap(async (req, res) =>
  res.json({ messages: await q.all('SELECT role,content,created_at FROM messages WHERE user_id=? ORDER BY id ASC LIMIT 200', [req.user.id]) })));
app.delete('/api/chat/history', auth, wrap(async (req, res) => {
  await q.run('DELETE FROM messages WHERE user_id=?', [req.user.id]); res.json({ ok: true });
}));

/* ---------------- image ---------------- */
const RES = { hd: [1920, 1080], '2k': [2560, 1440], '4k': [3840, 2160], square: [2048, 2048], portrait: [1620, 2880] };

app.post('/api/image', auth, wrap(async (req, res) => {
  const prompt = (req.body?.prompt || '').trim();
  if (!prompt) return res.status(400).json({ error: 'Décris ton image' });
  const [W, H] = RES[req.body?.resolution] || RES['4k'];
  const { svg, meta } = renderSVG(prompt, { width: W, height: H });
  const file = `img_${Date.now()}_${Math.random().toString(36).slice(2, 8)}.svg`;
  await saveFile(file, svg, 'image/svg+xml');
  const info = await q.run('INSERT INTO creations(user_id,type,prompt,file,meta) VALUES(?,?,?,?,?)',
    [req.user.id, 'image', prompt, file, JSON.stringify(meta)]);
  await log('image', `${req.user.pseudo}: ${prompt.slice(0, 60)}`);
  res.json({ id: info.lastInsertRowid, url: `/gen/${file}`, meta });
}));

/* ---------------- vidéo ---------------- */
app.post('/api/video', auth, wrap(async (req, res) => {
  const prompt = (req.body?.prompt || '').trim();
  if (!prompt) return res.status(400).json({ error: 'Décris ta vidéo' });
  const duration = Math.min(30, Math.max(3, Number(req.body?.duration) || 8));
  const scenes = Math.min(6, Math.max(2, Math.round(duration / 3)));
  const frames = [];
  for (let i = 0; i < scenes; i++) {
    const { svg } = renderSVG(`${prompt} [scene ${i + 1}]`, { width: 1920, height: 1080 });
    const f = `vid_${Date.now()}_${i}_${Math.random().toString(36).slice(2, 6)}.svg`;
    await saveFile(f, svg, 'image/svg+xml');
    frames.push(`/gen/${f}`);
  }
  const meta = { duration, scenes, fps: 30, resolution: '1920×1080', frames };
  const info = await q.run('INSERT INTO creations(user_id,type,prompt,file,meta) VALUES(?,?,?,?,?)',
    [req.user.id, 'video', prompt, frames[0], JSON.stringify(meta)]);
  await log('video', `${req.user.pseudo}: ${prompt.slice(0, 60)}`);
  res.json({ id: info.lastInsertRowid, frames, meta });
}));

