/* ---------------- tickets ---------------- */
app.post('/api/tickets', wrap(async (req, res) => {
  let uid = null, pseudo = 'Visiteur', email = (req.body?.email || '').trim();
  try {
    const t = req.cookies.foxia;
    if (t) {
      const p = jwt.verify(t, SECRET);
      const u = await q.get('SELECT * FROM users WHERE id=?', [p.id]);
      if (u) { uid = u.id; pseudo = u.pseudo; email = email || u.email; }
    }
  } catch {}
  const { category, subject, message, priority } = req.body || {};
  if (!subject || !message) return res.status(400).json({ error: 'Sujet et message obligatoires' });
  if (!email) return res.status(400).json({ error: 'Email obligatoire pour la réponse' });
  const info = await q.run('INSERT INTO tickets(user_id,pseudo,email,category,subject,message,priority) VALUES(?,?,?,?,?,?,?)',
    [uid, pseudo, email, category || 'bug', String(subject).slice(0, 160), String(message).slice(0, 4000), priority || 'normale']);
  await log('ticket', `#${info.lastInsertRowid} ${pseudo}: ${subject}`, 'warn');
  res.json({ ok: true, id: info.lastInsertRowid });
}));
app.get('/api/tickets/mine', auth, wrap(async (req, res) =>
  res.json({ tickets: await q.all('SELECT * FROM tickets WHERE user_id=? ORDER BY id DESC', [req.user.id]) })));

