app.get('/api/admin/stats', auth, admin, wrap(async (req, res) => {
  const one = async sql => Number((await q.get(sql)).c);
  res.json({
    users: await one('SELECT COUNT(*) AS c FROM users'),
    admins: await one("SELECT COUNT(*) AS c FROM users WHERE role='admin'"),
    banned: await one('SELECT COUNT(*) AS c FROM users WHERE banned=1'),
    tickets: await one('SELECT COUNT(*) AS c FROM tickets'),
    openTickets: await one("SELECT COUNT(*) AS c FROM tickets WHERE status='ouvert'"),
    urgent: await one("SELECT COUNT(*) AS c FROM tickets WHERE priority='urgente' AND status<>'resolu'"),
    creations: await one('SELECT COUNT(*) AS c FROM creations'),
    images: await one("SELECT COUNT(*) AS c FROM creations WHERE type='image'"),
    videos: await one("SELECT COUNT(*) AS c FROM creations WHERE type='video'"),
    sites: await one("SELECT COUNT(*) AS c FROM creations WHERE type='website'"),
    messages: await one('SELECT COUNT(*) AS c FROM messages'),
    today: await one("SELECT COUNT(*) AS c FROM users WHERE date(created_at)=date('now')"),
    settings: {
      siteName: await getSetting('site_name'), announcement: await getSetting('announcement'),
      maintenance: (await getSetting('maintenance')) === '1', signupsOpen: (await getSetting('signups_open')) === '1'
    }
  });
}));
app.get('/api/admin/tickets', auth, admin, wrap(async (req, res) => {
  const st = req.query.status;
  const rows = st && st !== 'tous'
    ? await q.all("SELECT * FROM tickets WHERE status=? ORDER BY (priority='urgente') DESC, id DESC", [st])
    : await q.all("SELECT * FROM tickets ORDER BY (status='ouvert') DESC, (priority='urgente') DESC, id DESC");
  res.json({ tickets: rows });
}));
app.patch('/api/admin/tickets/:id', auth, admin, wrap(async (req, res) => {
  const { status, admin_reply, priority } = req.body || {};
  const t = await q.get('SELECT * FROM tickets WHERE id=?', [req.params.id]);
  if (!t) return res.status(404).json({ error: 'Ticket introuvable' });
  await q.run(`UPDATE tickets SET status=COALESCE(?,status), admin_reply=COALESCE(?,admin_reply),
    priority=COALESCE(?,priority), updated_at=${PG ? 'NOW()' : "datetime('now')"} WHERE id=?`,
    [status || null, admin_reply ?? null, priority || null, req.params.id]);
  await log('ticket_update', `#${req.params.id} → ${status || t.status}`);
  res.json({ ticket: await q.get('SELECT * FROM tickets WHERE id=?', [req.params.id]) });
}));
app.delete('/api/admin/tickets/:id', auth, admin, wrap(async (req, res) => {
  await q.run('DELETE FROM tickets WHERE id=?', [req.params.id]); res.json({ ok: true });
}));
app.get('/api/admin/users', auth, admin, wrap(async (req, res) =>
  res.json({ users: await q.all(`SELECT id,pseudo,email,role,provider,banned,credits,avatar,created_at,
    (SELECT COUNT(*) FROM creations c WHERE c.user_id=users.id) AS creations FROM users ORDER BY id ASC`) })));
app.patch('/api/admin/users/:id', auth, admin, wrap(async (req, res) => {
  const { role, banned, credits } = req.body || {};
  const target = await q.get('SELECT * FROM users WHERE id=?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'Utilisateur introuvable' });
  if (Number(target.id) === 1 && (role === 'user' || banned === 1))
    return res.status(400).json({ error: 'Le fondateur ne peut pas être rétrogradé ni banni' });
  await q.run('UPDATE users SET role=COALESCE(?,role), banned=COALESCE(?,banned), credits=COALESCE(?,credits) WHERE id=?',
    [role || null, banned === undefined ? null : (banned ? 1 : 0), credits ?? null, req.params.id]);
  await log('user_update', `#${req.params.id} par ${req.user.pseudo}`);
  res.json({ ok: true });
}));
app.delete('/api/admin/users/:id', auth, admin, wrap(async (req, res) => {
  if (Number(req.params.id) === 1) return res.status(400).json({ error: 'Le compte fondateur est protégé' });
  await q.run('DELETE FROM users WHERE id=?', [req.params.id]);
  await q.run('DELETE FROM creations WHERE user_id=?', [req.params.id]);
  res.json({ ok: true });
}));
app.get('/api/admin/creations', auth, admin, wrap(async (req, res) => {
  const rows = await q.all('SELECT c.*,u.pseudo FROM creations c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.id DESC LIMIT 100');
  res.json({ creations: rows.map(r => ({ ...r, meta: JSON.parse(r.meta || '{}'), url: r.file ? `/gen/${r.file}` : null })) });
}));
app.get('/api/admin/logs', auth, admin, wrap(async (req, res) =>
  res.json({ logs: await q.all('SELECT * FROM logs ORDER BY id DESC LIMIT 200') })));
app.post('/api/admin/settings', auth, admin, wrap(async (req, res) => {
  const { siteName, announcement, maintenance, signupsOpen } = req.body || {};
  if (siteName !== undefined) await setSetting('site_name', siteName);
  if (announcement !== undefined) await setSetting('announcement', announcement);
  if (maintenance !== undefined) await setSetting('maintenance', maintenance ? '1' : '0');
  if (signupsOpen !== undefined) await setSetting('signups_open', signupsOpen ? '1' : '0');
  await log('settings', `mis à jour par ${req.user.pseudo}`);
  res.json({ ok: true });
}));

/* ---------------- fichiers générés (repli sur la base) ---------------- */
app.get('/gen/:name', wrap(async (req, res, next) => {
  const name = path.basename(req.params.name);
  const disk = path.join(GEN, name);
  if (fs.existsSync(disk)) return res.sendFile(disk);
  const f = await q.get('SELECT mime,content FROM files WHERE name=?', [name]);
  if (!f) return res.status(404).send('Fichier introuvable');
  try { fs.writeFileSync(disk, f.content); } catch (e) {}   // remise en cache disque
  res.type(f.mime).send(f.content);
}));

